"""Build the expanded proof edition from the editorial source below.
All proofs are educational reconstructions; source references point to the underlying
concepts, not to identical wording. No personal context is included.
"""
from pathlib import Path
import json, re
R=Path(__file__).resolve().parents[1]
C=json.loads((R/'data/chapters.json').read_text())
for c in C: c.pop('extraProofs',None)
D={c['id']:c for c in C}

def step(title,text,formula,hint):
    return {'title':title,'text':text,'math':formula,'hint':hint}
def setp(id,title,assumptions,idea,steps,scene=None):
    c=D[id]
    c['proof']={'title':title,'assumptions':assumptions,'idea':idea,'scene':scene or id,'kind':'教学重编证明','refs':c['refs']}
    c['derivation']=[step(*s) for s in steps]
def extra(id,title,assumptions,idea,steps,scene=None):
    c=D[id]
    c.setdefault('extraProofs',[]).append({'title':title,'assumptions':assumptions,'idea':idea,'scene':scene or id,'kind':'教学补充证明','refs':c['refs'],'steps':[step(*s) for s in steps]})

setp('start','下降、收敛与最优：三个命题不能互相替代','目标 f(x)=x²，定义域为实数；k 从 0 起。这里构造反例，不冒称某个优化算法。','想象台阶一直向下，却悬在谷底上方；台阶变小，只说明走得越来越少。',[
('先确定真正的终点','平方在所有实数上非负，并且只有零点取到零。因此原问题的最优解和值没有任何数值近似。',r'f(x)=x^2\ge0,\qquad x^*=0,\quad f^*=0.','图中横线 f*=0 是地面，不是人为设置的停止阈值。'),
('构造一直下降的点列','取正数序列。随着 k 增大，3 的负 k 次方严格下降，所以点仍保持正值且向左移动。',r'x_k=\frac12(1+3^{-k}),\quad x_k-x_{k+1}=3^{-(k+1)}>0.','注意每一步的位移都缩短。'),
('证明函数值逐步下降','使用平方差公式，两个因子都严格为正，故函数值确实严格下降。',r'f(x_k)-f(x_{k+1})=(x_k-x_{k+1})(x_k+x_{k+1})>0.','这一行证明了“下降”，尚未证明“到谷底”。'),
('计算极限而非猜终点','3 的负 k 次方趋零。由平方函数连续性，点列与目标值分别有下面的极限。',r'x_k\to\tfrac12,\qquad f(x_k)\to\tfrac14>0.','移动滑块后观察点停在 1/2，而不是 0。'),
('用最优性再次否定','无约束可微局部极小点必须驻定。该极限点的导数不为零，因此连局部极小都不是。',r'f^{\prime}(1/2)=2(1/2)=1\ne0.','图形与导数给出独立的检查。'),
('目标收敛甚至不保证点列收敛','乘上交替符号不会改变平方值，但偶数和奇数子列走向两个不同极限。',r'\tilde x_k=(-1)^kx_k,\quad\tilde x_{2k}\to\tfrac12,\quad\tilde x_{2k+1}\to-\tfrac12.','交替模式中函数值重合，空间位置却不重合。')])

setp('geometry','为什么 p≥1 的单位球凸，而 p<1 不凸？','有限维实向量；先讨论 1<p<∞，并单独处理 p=1、∞。','凸组合是一条线段；三角不等式保证整段不冲出单位球。',[
('从标量不等式开始','令共轭指数 q=p/(p−1)。最小化 t^p/p−bt 可得 Young 不等式；这为 Hölder 不等式提供逐项上界。',r'ab\le\frac{a^p}{p}+\frac{b^q}{q},\qquad a,b\ge0,\quad\frac1p+\frac1q=1.','这是把乘积拆成两种可相加的“预算”。'),
('归一化并求和得到 Hölder','对非零向量分别除以各自范数，逐坐标应用上式后求和；右边两部分的和为 1。零向量情形直接成立。',r'\sum_i |u_iv_i|\le\|u\|_p\|v\|_q.','向量方向不必相同，不等式仍成立。'),
('推出 Minkowski','把 |xᵢ+yᵢ| 的 p 次幂拆出一因子，先用绝对值三角不等式，再对两个和使用 Hölder。',r'\|x+y\|_p^p\le(\|x\|_p+\|y\|_p)\|x+y\|_p^{p-1}.','共同的最后一因子来自 q(p−1)=p。'),
('消去共同因子并补齐端点','当 x+y 非零时除以其范数的 p−1 次方；为零则结论直接成立。p=1 逐项相加，p=∞ 对最大值使用同样的标量三角不等式。',r'\|x+y\|_p\le\|x\|_p+\|y\|_p,\qquad1\le p\le\infty.','证明覆盖所有点，而不只图上两端点。'),
('三角不等式推出球的凸性','范数正齐次性把凸组合的两个系数提出；端点的范数各不超过 1。',r'\|(1-t)x+ty\|_p\le(1-t)\|x\|_p+t\|y\|_p\le1.','整条线段的每个 t 都被同一个上界约束。'),
('p<1 的一个中点就足够','选坐标轴上的单位端点，直接计算中点。它的值严格超过 1，所以中点在单位球外，也同时否定三角不等式。',r'x=(1,0),\ y=(0,1),\quad\|(x+y)/2\|_p=2^{1/p-1}>1\quad(0<p<1).','拖到 p=0.5，看中点如何穿出边界。')])

setp('differentiation','中心差分为什么先变准、再可能变差？','沿所测坐标方向三阶导数有界；浮点误差模型是量级估计，不保证每个 h 都有相同常数。','正、负两个小步相减，偶次项抵消；但数字太接近时，相减也会丢失有效位。',[
('降成一维函数','固定点和方向 eᵢ，把多元问题限制在一条坐标直线上。链式法则给出该一维导数。',r'\phi(t)=f(x+te_i),\qquad\phi^{\prime}(0)=\partial_i f(x).','图上的割线只沿一个方向，不是完整梯度。'),
('分别向左右展开','在零点应用带三阶余项的 Taylor 公式。左右的二次项相同，而一次项符号相反。',r'\phi(\pm h)=\phi(0)\pm h\phi^{\prime}(0)+\tfrac{h^2}{2}\phi^{\prime\prime}(0)+R_\pm,\quad |R_\pm|\le Mh^3/6.','对称位置是抵消二次偏差的关键。'),
('相减再除以距离','两式相减并除以 2h；三阶余项之差除以 h 后是二阶误差。',r'\left|\frac{\phi(h)-\phi(-h)}{2h}-\phi^{\prime}(0)\right|\le Mh^2/6.','割线斜率以 h² 的量级逼近切线斜率。'),
('加入函数求值误差','若每次求值的绝对误差不超过 εB，两个误差相减后再除以 2h，最坏界为 εB/h。',r'\widehat\phi(\pm h)=\phi(\pm h)+\delta_\pm,\quad|\delta_\pm|\le\varepsilon B\Rightarrow |E_{\rm round}|\le\varepsilon B/h.','两个大而相近的数相减，会把相对误差放大。'),
('合并两种误差','一项随 h 缩小而减小，另一项随 h 缩小而增大；这解释常见趋势，不要求实际曲线严格 U 形。',r'|E|\le Ah^2+\varepsilon B/h,\qquad A=M/6.','查看真实差分曲线的抖动，而非理想化插图。'),
('平衡而非一味缩小','当 A、B 为正且量级模型适用时，对误差上界求极小给出 h 的立方根尺度；A=0 的纯二次函数不适用这个平衡式。',r'2Ah-\varepsilon B/h^2=0\Rightarrow h=(\varepsilon B/(2A))^{1/3}.','最合适的 h 依赖函数尺度，不能固定为任意极小数。')])

setp('convex','凸性、支撑平面与非负曲率为什么等价？','f 在开凸域上可微；涉及 Hessian 时假设 f 二次连续可微。结论不适用于只有一个采样点曲率为正的情形。','弦在上面、切线在下面，是同一种几何从有限尺度和无限小尺度看到的样子。',[
('把凸性写在线段上','固定域中任意 x、y，对 0<t≤1 使用凸组合定义；凸域保证整条线段合法。',r'f(x+t(y-x))\le(1-t)f(x)+tf(y).','图中绿色弦连接端点，而曲线位于弦下。'),
('除以 t 并取右极限','移项得到差商上界。令 t 趋零，可微性把差商换成方向导数。',r'\frac{f(x+t(y-x))-f(x)}t\le f(y)-f(x)\Rightarrow f(y)\ge f(x)+\nabla f(x)^T(y-x).','把弦的一端推向 x，弦极限成为切线。'),
('反向：在中间点写两次支撑','设 z=(1−t)x+ty，分别对 x、y 使用 z 处的支撑不等式。',r'f(x)\ge f(z)+\nabla f(z)^T(x-z),\quad f(y)\ge f(z)+\nabla f(z)^T(y-z).','用同一条切平面同时支撑左右端点。'),
('加权后梯度项抵消','第一式乘 1−t，第二式乘 t，再相加；两个方向的加权和为零。',r'(1-t)(x-z)+t(y-z)=0\Rightarrow f(z)\le(1-t)f(x)+tf(y).','梯度项抵消是支撑条件足以推出凸性的原因。'),
('Hessian 半正定推出支撑','沿线段积分两次，余项是方向曲率的非负加权积分。',r'f(y)-f(x)-\nabla f(x)^T(y-x)=\int_0^1(1-s)(y-x)^T\nabla^2f(x+s(y-x))(y-x)\,ds\ge0.','非负曲率让曲线从切线向上弯。'),
('凸性也迫使方向曲率非负','对任意方向 d，把 x 作为对称两点的中点。二次 Taylor 展开后除以 h² 取极限。',r'f(x+hd)+f(x-hd)-2f(x)\ge0\Rightarrow d^T\nabla^2f(x)d\ge0.','必须对任意方向成立，才是 Hessian 半正定。'),
('核对图中的四次例子','二阶导数为 3x²+a。当 a≥0 时处处非负；当 a<0 时在 x=0 已经发现负曲率。',r'f(x)=x^4/4+ax^2/2,\quad f^{\prime\prime}(x)=3x^2+a,\quad f\text{ 全域凸}\iff a\ge0.','一条弦没有越界，只是一次检查；负曲率则能直接证伪。')])

setp('conjugacy','Fenchel–Young 间隙、次梯度与共轭二次型','f 是适当凸函数；讨论接触等号时 x 在有效域内。二次例子要求 a>0。','给定斜率后，把直线往上抬到刚好碰到曲线；共轭值记录需要减掉多少截距。',[
('上确界天然压住每个候选','共轭对所有 z 求上确界，所以将 z 取为任意固定 x 只会让值变小或相等。',r'f^*(y)=\sup_z(y^Tz-f(z))\ge y^Tx-f(x).','试探点不是接触点时，直线与曲线之间还有空隙。'),
('移项得到基本不等式','把原函数项移到左边，得到对所有 x、y 成立的 Fenchel–Young 不等式。',r'f(x)+f^*(y)-y^Tx\ge0.','间隙是非负量，可以做最优性证书。'),
('刻画等号','等号意味着 x 已经实现上确界，因此其他任意 z 都不能给出更大的值。把该关系移项。',r'f^*(y)=y^Tx-f(x)\iff f(z)\ge f(x)+y^T(z-x)\quad\forall z.','这正是斜率 y 的直线在 x 接触并全局支撑。'),
('辨认次梯度定义','上一行右边是 y 属于次微分的定义。若 f 可微，支撑斜率就是唯一的梯度。',r'f(x)+f^*(y)=y^Tx\iff y\in\partial f(x);\qquad f\text{ 可微时 }y=\nabla f(x).','尖点可能有一整段合法斜率，而不是唯一切线。'),
('求二次函数共轭','对 yx−ax²/2 求导为零；a>0 使它严格凹，驻点是唯一全局最大点。',r'x_c=y/a,\qquad f^*(y)=yx_c-ax_c^2/2=y^2/(2a).','改变斜率时，接触点沿抛物线移动。'),
('把间隙配成平方','将二次公式代入再配方，非负性和等号位置完全可见。',r'\frac a2x^2+\frac{y^2}{2a}-xy=\frac a2(x-y/a)^2.','图中的竖直间隙正是右边的平方。'),
('尖点的共轭不是尖点','对于 |x|，若 |y|≤1，则 yx−|x|≤0，取 x=0 达到零；否则沿 y 的符号令 |x| 趋无穷。',r'(|\cdot|)^*(y)=\begin{cases}0,&|y|\le1,\\+\infty,&|y|>1.\end{cases}','后面 L₁ 惩罚变成盒约束，根源就在这里。')])

setp('modeling','岭回归与 LASSO 的最优性为什么不同？','Q 对称正定，λ≥0。损失为 ℓ(x)=xᵀQx/2−bᵀx+c；岭惩罚使用 λ‖x‖²/2。','光滑惩罚持续拉回系数，尖点惩罚则能在零点提供一整段“平衡力”。',[
('先看损失的曲率','对二次式求导。正定 Hessian 保证严格凸，且二次增长保证最小值存在。',r'\nabla\ell(x)=Qx-b,\quad\nabla^2\ell(x)=Q\succ0.','等高椭圆的中心是无正则解。'),
('无正则：解力平衡','可微凸问题的零梯度既必要又充分，故只需求解 Qx=b。',r'x_{\rm LS}=Q^{-1}b.','数值实现应解方程，而非显式构造逆矩阵。'),
('岭回归：连续的恢复力','惩罚梯度为 λx。令总梯度为零，Q+λI 仍正定，唯一解存在。',r'0=Qx-b+\lambda x\Rightarrow (Q+\lambda I)x_{\rm ridge}=b.','圆形惩罚没有折角，通常只连续收缩。'),
('LASSO：使用次微分','绝对值在正负侧的导数为 ±1，在零点的次微分为闭区间。凸函数最优性写为零属于次微分。',r'0\in Qx-b+\lambda\partial\|x\|_1,\qquad\partial|0|=[-1,1].','零点的区间可以抵消一段范围内的损失梯度。'),
('逐坐标分情况','非零系数固定了次梯度符号；零系数则只要求损失梯度落在 λ 宽度的区间里。',r'x_i\ne0:\ (Qx-b)_i=-\lambda\operatorname{sign}(x_i);\quad x_i=0:\ |(Qx-b)_i|\le\lambda.','这不是对小数做事后截断，而是优化条件精确选出零。'),
('对角 Q 才能完全分离','若 Q 是对角矩阵，每个坐标都是独立一维问题；一般 Q 的交叉项会把其他坐标带入当前条件。',r'Q=\operatorname{diag}(q_i)\Rightarrow x_i^*=S_\lambda(b_i)/q_i.','切换相关案例，看一个系数改变如何带动另一个。'),
('活动集枚举为什么能作为二维参照','对每个坐标枚举负、零、正三种状态，解非零子系统，再核对符号与零坐标不等式。通过条件的解即为全局最优，严格凸性保证唯一。',r'Q_{AA}x_A=b_A-\lambda s_A,\quad x_{A^c}=0,\quad s_A=\operatorname{sign}(x_A).','参照解独立于 PG、ADMM 等迭代器，不把迭代终点当作真值。')])

setp('cones','2×2 半正定约束为什么等价于二阶锥？','X 是 2×2 实对称矩阵；半正定指所有实向量方向的二次型非负。','把两个特征值看成“平均值 ± 各向异性半径”；平均值必须盖住整个半径。',[
('分离平均值和差值','以 t 表示两个对角元的平均，u 表示一半差值；重写矩阵。',r't=(a+c)/2,\quad u=(a-c)/2,\quad X=\begin{pmatrix}t+u&b\\b&t-u\end{pmatrix}.','锥的竖直方向是平均值 t，横向半径是 (u,b)。'),
('求特征多项式','行列式等于两个对角项的乘积减去 b²。配成平方后，可直接求两个根。',r'\det(X-\eta I)=(t-\eta)^2-u^2-b^2.','半径变大，会把小特征值向零以下拉。'),
('写出两个特征值','平方根非负，故减号对应最小特征值。',r'\eta_\pm=t\pm\sqrt{u^2+b^2},\qquad\eta_-\le\eta_+.','最小特征值控制最危险的方向。'),
('解释谱判据的充分必要性','实对称矩阵可正交对角化。任意方向的二次型是各坐标平方乘对应特征值之和。',r'X=V\operatorname{diag}(\eta_-,\eta_+)V^T,\quad d^TXd=\eta_-z_1^2+\eta_+z_2^2,\ z=V^Td.','若小特征值为负，取对应特征向量就得到反例。'),
('把谱判据改写为锥约束','所有方向非负等价于最小特征值非负，再移项得到标准二阶锥。',r'X\succeq0\iff\eta_-\ge0\iff t\ge\sqrt{u^2+b^2}=\|(u,b)\|_2.','实验中的锥裕量与最小特征值实际上是同一个数。'),
('边界与退化情况','锥边界对应最小特征值为零。若 t=0，则锥约束迫使 u=b=0，矩阵只能是零矩阵。',r't=\|(u,b)\|_2\Rightarrow\det X=0;\quad t=0,\ X\succeq0\Rightarrow X=0.','边界不是计算失败，而是秩下降。')])
extra('cones','最大 k 项之和的阈值表示','a₁,…,aₙ 为任意实数，1≤k≤n；a_[i] 按降序排列。','一个阈值把数列分成上面要付超额、下面不用付的两部分。',[
('给任何阈值建立下界','对最大的 k 项，每项正部至少等于该项减去 t；其余项的正部非负。',r'\sum_i(a_i-t)_+\ge\sum_{i=1}^k(a_{[i]}-t).','越过阈值的柱子支付超过阈值的高度。'),
('移项形成普遍下界','两边加上 kt，阈值项相消。该界对任意 t 成立。',r'kt+\sum_i(a_i-t)_+\ge\sum_{i=1}^k a_{[i]}.','任何阈值都不能低估最大 k 项之和。'),
('选择能取等的阈值','当 k<n 时选 a_[k+1]≤t≤a_[k]；前 k 项均不小于 t，剩余均不大于 t。并列值不影响结论。',r'kt+\sum_i(a_i-t)_+=kt+\sum_{i=1}^k(a_{[i]}-t).','把阈值放到第 k 与第 k+1 根柱子之间。'),
('处理 k=n 的端点','此时只需 t≤minᵢaᵢ，所有正部均等于原差值，因此也取等。',r'\sum_{i=1}^k a_{[i]}=\min_{t\in\mathbb R}\left[kt+\sum_i(a_i-t)_+\right].','不需要不存在的第 n+1 项。'),
('转为辅助变量约束','把每个正部替换为一个非负、且不小于 aᵢ−t 的变量。最小化会使其恰好等于正部。',r'\min_{t,z}\ kt+\sum_i z_i,\qquad z_i\ge0,\ z_i\ge a_i-t.','若 aᵢ 是仿射表达式，这就是线性建模结构。')],scene='topk')

setp('optimality','一阶必要、二阶必要与二阶充分条件','f 在候选点邻域可微；二阶结论假设二次连续可微。这里是无约束问题。','先看斜坡是否消失，再看各个方向是否向上弯；平坦时必须继续检查更高阶。',[
('任何方向都不能立即下降','局部极小点附近的所有小扰动都不能更小。固定方向 d，对正负 t 比较方向差商。',r'\phi(t)=f(x^*+td),\quad \phi(t)\ge\phi(0)\text{ 对充分小 }|t|.','无约束时正反两个方向都合法。'),
('正反方向夹出零导数','右差商非负、左差商非正；可微性迫使共同极限为零。任意 d 都成立，故梯度为零。',r'\phi^{\prime}(0)=\nabla f(x^*)^Td=0\quad\forall d\Rightarrow\nabla f(x^*)=0.','梯度不为零时，沿负梯度总能找到更低邻点。'),
('必要的二阶条件','一阶项为零后，对 t 与 −t 的函数增量相加，再除以 t² 取极限。',r'0\le\frac{f(x^*+td)+f(x^*-td)-2f(x^*)}{t^2}\to d^TH_*d.','任意负曲率方向都会否定局部极小。'),
('正定曲率形成统一余量','若 H* 正定，令最小特征值为 m>0。Taylor 余项相对 ‖d‖² 趋零，充分小时绝对值不超过 m‖d‖²/4。',r'f(x^*+d)-f(x^*)=\tfrac12d^TH_*d+o(\|d\|^2)\ge\tfrac m4\|d\|^2>0.','二次项的正余量压住了更高阶小项。'),
('零曲率并不能决定符号','x⁴ 和 −x⁴ 在零点都具有零梯度、零 Hessian，但一个严格极小，另一个严格极大。',r'f_+(x)=x^4,\quad f_-(x)=-x^4,\quad f_\pm^{\prime}(0)=f_\pm^{\prime\prime}(0)=0.','二阶检查“无法判断”不等于“不是极小”。'),
('凸性把驻定提升为全局证书','对可微凸函数使用已证明的支撑不等式，梯度为零时右侧就是 f(x*)。',r'f(y)\ge f(x^*)+\nabla f(x^*)^T(y-x^*)=f(x^*)\quad\forall y.','非凸双井图不能使用这一全局推论。')])

setp('duality','弱对偶与凸 KKT 的充分性','不等式写作 gᵢ(x)≤0，乘子 λᵢ≥0；凸 KKT 充分性还要求目标、gᵢ 凸，等式为仿射。','原始可行解从上面压最优值，对偶可行解从下面托最优值；两边相遇就是证书。',[
('定义拉格朗日函数','乘子把约束的违背写成附加项。对偶函数必须对全部原始变量取下确界，而不只对可行点。',r'\mathcal L(x,\lambda,\nu)=f(x)+\sum_i\lambda_i g_i(x)+\nu^T(Ax-b),\quad q(\lambda,\nu)=\inf_x\mathcal L(x,\lambda,\nu).','先固定支撑斜率，再找整条曲线的最低点。'),
('可行性确定不等号方向','对原始可行 x，等式项为零；λᵢ 非负且 gᵢ≤0，使不等式附加项非正。',r'q(\lambda,\nu)\le\mathcal L(x,\lambda,\nu)\le f(x).','乘子符号若写反，作为下界的逻辑就失效。'),
('分别取最优得到弱对偶','上式对任意两边的可行选择成立，因此对 x 取最小、对乘子取最大仍保留顺序。',r'd^*:=\sup_{\lambda\ge0,\nu}q(\lambda,\nu)\le p^*:=\inf_{x\text{ 可行}}f(x).','弱对偶不需要凸性；零间隙则需要额外条件。'),
('凸驻定使拉格朗日函数最小','凸假设使固定非负乘子后的拉格朗日函数凸。KKT 驻定因此使 x* 成为该函数的全局最小点。',r'0\in\partial_x\mathcal L(x^*,\lambda^*,\nu^*)\Rightarrow q(\lambda^*,\nu^*)=\mathcal L(x^*,\lambda^*,\nu^*).','这一步才真正使用凸性。'),
('互补与可行性使上下界相遇','互补条件让每个 λᵢgᵢ 消失，等式可行性消去 ν 项；弱对偶夹出最优性。',r'q(\lambda^*,\nu^*)=f(x^*),\qquad q\le p^*\le f(x^*)\Rightarrow p^*=f(x^*).','四类 KKT 条件合在一起消灭了间隙。'),
('计算图中的一维对偶','目标为 (x−a)²/2，约束为 c−x≤0。对 x 求导并代回得到凹二次函数。',r'x(\lambda)=a+\lambda,\qquad q(\lambda)=\lambda(c-a)-\lambda^2/2.','对偶最大化是一条开口向下的抛物线。'),
('显式验证活跃与不活跃情况','若 c≤a，无约束解可行，λ*=0；若 c>a，边界活跃，λ*=c−a。两种情况统一如下。',r'\lambda^*=(c-a)_+,\quad x^*=\max(a,c),\quad f(x^*)=q(\lambda^*)=\tfrac12(c-a)_+^2.','移动 c 穿过 a，观察约束何时开始施力。')])

setp('line-search','Armijo 回溯为什么有限次终止？','f 在 x 可微，d 是严格下降方向，0<c₁<1，0<β<1，初始 α₀>0。定理忽略有限精度和实现中的回溯次数上限。','真正的曲线在足够近处会贴近切线；Armijo 只要求切线承诺的一部分下降。',[
('把下降方向记成负斜率','固定当前点和方向，令 m 为方向导数。下降性意味着 m 严格为负。',r'm=\nabla f(x)^Td<0.','橙色参照线只保留 c₁ 比例的斜率。'),
('使用可微性的精确定义','余项除以 α 趋零，因此真实函数沿方向的变化等于线性变化加上更小量。',r'f(x+\alpha d)=f(x)+\alpha m+r(\alpha),\quad r(\alpha)/\alpha\to0.','曲线与切线的竖直差比 α 还小。'),
('给余项预留明确预算','设 ε=(1−c₁)(−m)/2>0。由极限定义，存在 ᾱ>0，使 0<α≤ᾱ 时 |r(α)|≤εα。',r'|r(\alpha)|\le\tfrac12(1-c_1)(-m)\alpha.','只要缩得足够近，余项就不可能耗尽全部下降。'),
('代回比较 Armijo 右侧','移项后是一个负的线性项加一个至多一半大小的余项，和仍为负。',r'f(x+\alpha d)-f(x)-c_1\alpha m\le\tfrac12(1-c_1)\alpha m<0.','充分小的候选会落在允许区域内。'),
('几何缩小必定进入安全区','β 的整数次幂趋零，因此存在有限 j 使 α₀βʲ≤ᾱ；第一次满足判据最迟出现在某个有限 j。',r'\alpha_j=\alpha_0\beta^j\to0\Rightarrow\exists j<\infty:\ \alpha_j\le\bar\alpha.','候选步长一格一格向左缩，不需要碰运气。'),
('L 光滑时给出显式阈值','下降引理给二次余项上界。将其与 Armijo 比较并移项，得到一个充分步长。',r'\alpha\le\frac{-2(1-c_1)m}{L\|d\|^2}\Rightarrow f(x+\alpha d)\le f(x)+c_1\alpha m.','这是充分条件，不是每次必须取到的最大步长。')])

setp('gradient','正定二次型的步长稳定区与最优固定步长','Q 对称正定，谱落在 [μ,L]，0<μ≤L；固定 α，目标为二次型。','每个特征方向都是独立的弹簧；同一 α 在硬弹簧上可能过冲，在软弹簧上却几乎不动。',[
('从精确最优点定义误差','最优点满足 Qx*=b。把它从梯度迭代两侧减去，常数项完全消失。',r'e_k=x_k-x^*,\quad e_{k+1}=(I-\alpha Q)e_k.','现在研究的是离终点多远，而不是绝对坐标。'),
('换到互不耦合的谱坐标','正交对角化 Q，令 z=Vᵀe。每个方向只乘一个标量，不再互相影响。',r'Q=V\operatorname{diag}(\lambda_i)V^T,\quad z_{k+1,i}=(1-\alpha\lambda_i)z_{k,i}.','沿椭圆长短轴分别看，轨迹就像两个一维递推。'),
('辨认收缩和翻转','绝对值小于 1 表示幅度缩小，系数为负表示每步翻到终点另一侧。',r'|1-\alpha\lambda_i|<1\iff0<\alpha\lambda_i<2.','翻转本身未必有害，翻转后幅度变大才是失稳。'),
('所有方向同时收缩','最严格限制由最大特征值 L 给出。该条件保证对任意初值收敛；边界或更大步长仍可能对缺少危险分量的特殊初值收敛。',r'0<\alpha<2/L,\quad \|e_k\|\le\bigl(\max_i|1-\alpha\lambda_i|\bigr)^k\|e_0\|.','αL=2 时，高曲率分量的系数恰好是 −1。'),
('平衡最慢的两个端点','最坏收缩率由谱区间端点控制。把两端误差因子的绝对值设为相等，可使最大者最小。',r'1-\alpha\mu=-(1-\alpha L)\Rightarrow\alpha_*=2/(L+\mu),\quad r_*=(L-\mu)/(L+\mu).','κ=L/μ 越大，最佳收缩率也越接近 1。'),
('精确线搜索另有一个公式','固定负梯度方向，展开一元二次目标，再对 α 求导为零；g 非零且 Q 正定保证分母为正。',r'f(x-\alpha g)=f(x)-\alpha g^Tg+\tfrac{\alpha^2}{2}g^TQg\Rightarrow\alpha_{\rm exact}=\frac{g^Tg}{g^TQg}.','每步方向上的最优，不代表总路径最短。')])

setp('subgradient','次梯度最好迭代点的完整误差界','f 凸且有最优点 x*；gₖ∈∂f(xₖ)，‖gₖ‖≤G，αₖ>0。k=0,…,T−1。','不强求每次都下坡，而把“离解的平方距离”当成账户：每次误差收益扣除步长噪声成本。',[
('凸性提供内积下界','在当前点写出对最优点的次梯度支撑式，再移项。',r'f(x^*)\ge f(x_k)+g_k^T(x^*-x_k)\Rightarrow g_k^T(x_k-x^*)\ge\Delta_k:=f(x_k)-f^*.','次梯度是支撑斜率，不必指向一次下降的有限步。'),
('逐项展开平方距离','将更新 xₖ₊₁=xₖ−αₖgₖ 代入平方范数，用内积展开。',r'\|x_{k+1}-x^*\|^2=\|x_k-x^*\|^2-2\alpha_kg_k^T(x_k-x^*)+\alpha_k^2\|g_k\|^2.','中间负项是进展，最后正项是跨步过大的代价。'),
('替换并整理','用第一步把内积换成目标间隙，并用 G 控制次梯度范数。',r'2\alpha_k\Delta_k\le\|x_k-x^*\|^2-\|x_{k+1}-x^*\|^2+\alpha_k^2G^2.','图上偶尔上升的目标，不会否定这个距离不等式。'),
('求和并消去中间距离','从 0 加到 T−1，相邻距离正负抵消；末项非正可以去掉得到更宽的上界。',r'2\sum_{k<T}\alpha_k\Delta_k\le\|x_0-x^*\|^2+G^2\sum_{k<T}\alpha_k^2.','这里只剩初始账户与累计步长成本。'),
('从加权和提取最好值','每个 Δₖ 都不小于历史最小值，且权重 αₖ 为正，所以可以提取最小值后除以权重和。',r'\min_{k<T}\Delta_k\le\frac{D^2+G^2\sum_{k<T}\alpha_k^2}{2\sum_{k<T}\alpha_k},\quad D=\|x_0-x^*\|.','界控制最好迭代点，不保证最后一点每步都更好。'),
('选定总预算得到平方根速率','若事先知道 T、D 且 G>0，取常数 α=D/(G√T)，分子两项相等。D=0 时初值已最优。',r'\alpha=\frac{D}{G\sqrt T}\Rightarrow\min_{k<T}\Delta_k\le\frac{DG}{\sqrt T}.','这不是随时可用的万能步长：它用到了预算和距离信息。')])

setp('newton','牛顿方向何时下降，何时二次收敛？','局部速率结论：∇f(x*)=0，邻域内 Hessian 为 L_H-Lipschitz 且逆范数统一≤M；初值充分近，取精确完整牛顿步。','线性模型把梯度拉到零；当曲率变化很小，剩余误差是二阶小量。',[
('建立梯度的一阶模型','把下一点的梯度写成当前梯度加 Hessian 乘位移，再令线性部分为零。',r'g(x+d)\approx g(x)+H(x)d,\quad H(x)d=-g(x).','寻找的是梯度的零，不是盲目朝图中最低处冲。'),
('正定曲率确保下降','若 H 正定且 g 非零，逆矩阵也正定；代回方向导数得到严格负值。',r'g^Td=-g^TH^{-1}g<0.','H 不定时这条负号保证失效。'),
('把真实梯度写成积分','设 e=x−x*。沿两点的线段积分 Hessian，并使用 g(x*)=0。',r'g(x)=\int_0^1H(x^*+se)e\,ds.','真实梯度是沿途曲率的平均，而牛顿只用当前位置曲率。'),
('推导下一步误差恒等式','完整步为 x⁺=x−H(x)⁻¹g(x)。代入积分，合并成 Hessian 差。',r'e^+=H(x)^{-1}\int_0^1[H(x)-H(x^*+se)]e\,ds.','误差来源只剩“当前位置曲率”与“沿途曲率”的不一致。'),
('用 Lipschitz 条件估计','两个位置相距 (1−s)‖e‖，故矩阵差范数不超过 L_H(1−s)‖e‖；再乘逆范数并积分。',r'\|e^+\|\le ML_H\|e\|^2\int_0^1(1-s)\,ds=\tfrac{ML_H}{2}\|e\|^2.','误差平方：误差缩小十倍，下一次量级可能缩小百倍。'),
('说明“初值充分近”的作用','取邻域半径 r 使 ML_H r/2<1，且该球内所有假设成立，则新误差更小，迭代留在这个邻域内。',r'\|e_0\|\le r,\quad (ML_H/2)r<1\Rightarrow\|e_{k+1}\|\le(ML_H/2)\|e_k\|^2.','局部保证不能自动控制远处或错误驻点的吸引域。'),
('解释平移保护但不混淆定理','给 Hessian 添加足够的单位阵平移使最小特征值至少为 δ>0，再用线搜索。保护步的全局机制与上面的完整步局部速率分开。',r'\widetilde H=H+\max(0,\delta-\lambda_{\min}(H))I\succeq\delta I.','观察保护模式如何拒绝指向极大点的方向。')])

setp('quasi-newton','逆 BFGS 如何同时满足割线条件与保持正定？','H 对称正定，sᵀy>0，ρ=1/(sᵀy)。这里 H 近似 Hessian 的逆。','历史只测到一个方向的曲率；更新沿这个方向校准，同时保住其他方向的正能量。',[
('固定记号，避免逆与正混淆','位移 s 是两次位置之差，y 是两次梯度之差。逆近似需要把 y 映射回 s。',r's=x_{k+1}-x_k,\quad y=g_{k+1}-g_k,\quad H_+y=s.','测量到的是“走了 s，梯度变了 y”。'),
('给出低秩更新','定义 V=I−ρsyᵀ，更新为 VHVᵀ 加一个秩一正项。',r'H_+=VHV^T+\rho ss^T,\qquad V=I-\rho sy^T.','第一项修正旧度量，第二项补上新观测。'),
('直接验证割线条件','因为 Vᵀy=y−ρy(sᵀy)=0，第一项作用在 y 上消失；第二项恰好得到 s。',r'H_+y=VH(V^Ty)+\rho s(s^Ty)=s.','这是一条代入恒等式，不需要数值收敛。'),
('先看对称性','H 对称时 VHVᵀ 对称，ssᵀ 也对称；两者相加仍对称。',r'H_+^T=VH^TV^T+\rho ss^T=H_+.','几何度量不能偷偷变成非对称矩阵。'),
('把二次型拆成两个非负项','对任意 z，旧 H 正定、ρ>0，所以两个项均非负。',r'z^TH_+z=(V^Tz)^TH(V^Tz)+\rho(s^Tz)^2\ge0.','每一项都是一个平方型能量。'),
('排除非零向量取零','若总和为零，则 sᵀz=0 且 Vᵀz=0。但 sᵀz=0 时 Vᵀz=z，所以只能 z=0。',r'z^TH_+z=0\Rightarrow s^Tz=0,\quad V^Tz=z=0\Rightarrow H_+\succ0.','这一步从半正定提升到严格正定。'),
('Wolfe 为什么提供正曲率','若 d 为下降方向，s=αd，Wolfe 曲率条件为 g₊ᵀd≥c₂gᵀd，其中 c₂<1。由此 sᵀy≥α(c₂−1)gᵀd>0。',r's^Ty=\alpha(g_+^Td-g^Td)\ge\alpha(c_2-1)g^Td>0.','Armijo 单独没有这个保证，故演示要检查并跳过坏曲率对。')])

setp('trust','信赖域子问题的全局最优证书为何成立？','模型 m(d)=gᵀd+dᵀHd/2，H 对称，半径 Δ>0。本证明给出所列证书的充分性及构造解释，不将非凸一般 KKT 当作充分。','把不定模型加一个球形曲率修正；在球内，修正模型和半径互补一起排除更优点。',[
('先写全部证书','候选 d* 满足可行性、非负乘子、移位后的驻定与半正定，以及互补条件。',r'(H+\lambda I)d^*=-g,\quad H+\lambda I\succeq0,\quad\lambda\ge0,\quad\|d^*\|\le\Delta,\quad\lambda(\|d^*\|^2-\Delta^2)=0.','不能只检查解了线性方程；还要检查曲率和半径。'),
('比较任意可行点','令 h=d−d*，对二次模型做精确展开，没有 Taylor 余项。',r'm(d)-m(d^*)=(g+Hd^*)^Th+\tfrac12h^THh.','这是全局二次恒等式，不是邻域近似。'),
('使用移位驻定重组','g+Hd*=−λd*。将 H 分成 H+λI 与 −λI，再用平方范数展开合并 λ 项。',r'm(d)-m(d^*)=\tfrac12h^T(H+\lambda I)h+\tfrac\lambda2(\|d^*\|^2-\|d\|^2).','模型差被拆成两个能证明非负的部分。'),
('两个部分都非负','第一项由半正定保证；λ=0 时第二项为零，λ>0 时互补使 ‖d*‖=Δ≥‖d‖。',r'm(d)-m(d^*)\ge0\quad\forall\|d\|\le\Delta.','因此得到全局最优，而不仅是一个驻点。'),
('普通边界解化为一元求根','在 H 的特征坐标中，非奇异移位给出各方向分量；令范数等于 Δ。',r'\widehat d_i=-\widehat g_i/(\eta_i+\lambda),\quad\sum_i\widehat g_i^2/(\eta_i+\lambda)^2=\Delta^2.','增大 λ 会缩短常规方向上的步长。'),
('hard case 补上缺失方向','若 λ=−ηmin≥0 且梯度在最小特征子空间上为零，解可以加上零空间分量。选择该分量补足半径，再检查上面的证书。',r'd^*=-(H+\lambda I)^\dagger g+v,\quad v\in\ker(H+\lambda I),\quad\|d^*\|=\Delta.','没有负曲率边界分量，可能错过真正的最小点。'),
('回到原目标检查模型可信度','二次子问题解得再好，也只优化模型。实际下降除以预测下降，决定是否接受候选以及调整半径。',r'\rho=\frac{f(x)-f(x+d)}{-g^Td-d^THd/2},\quad\text{仅在预测下降}>0\text{时使用该比值。}','拒绝的步骤也是算法知识，不能从动画中删除。')])

setp('least-squares','Gauss–Newton 从残差线性化到正规方程','r:ℝⁿ→ℝᵐ 二次可微；J 为残差 Jacobian。需要唯一 Gauss–Newton 步时要求 J 列满秩；LM 使用 μ>0。','先把每个残差当成小直线，再让这些直线的平方和最小；不是直接忽略所有二阶信息。',[
('从分量求目标梯度','目标为各残差平方的一半。逐项链式求导，再把所有残差梯度收进 J 的行。',r'F=\tfrac12\sum_i r_i^2,\quad\nabla F=\sum_i r_i\nabla r_i=J^Tr.','大残差对梯度的贡献更大。'),
('再求导得到精确 Hessian','对 rᵢ∇rᵢ 使用乘积法则，一部分来自一阶梯度外积，另一部分来自残差自身的曲率。',r'\nabla^2F=\sum_i\nabla r_i\nabla r_i^T+\sum_i r_i\nabla^2r_i=J^TJ+\sum_i r_i\nabla^2r_i.','Gauss–Newton 保留第一部分，不是把 Hessian 全扔掉。'),
('建立线性化残差子问题','先取 r(x+d)≈r+Jd，然后最小化该向量的平方范数。',r'\min_d\ \tfrac12\|r+Jd\|^2.','曲线拟合图中，局部预测随参数线性改变。'),
('对 d 求导','二次子问题梯度为 Jᵀ(r+Jd)。令其为零即得到正规方程；列满秩时 JᵀJ 正定。',r'J^TJd=-J^Tr,\qquad z^TJ^TJz=\|Jz\|^2>0\quad(z\ne0).','秩不足时不能随便求逆。'),
('解释忽略项什么时候小','三角不等式给出 Hessian 误差上界；若残差趋零、二阶导数有界，该项随之趋零。',r'\|\nabla^2F-J^TJ\|\le\sum_i|r_i|\,\|\nabla^2r_i\|.','残差小是一条结构条件，不等于任何初始点都好。'),
('LM 增加距离成本','对子问题加 μ‖d‖²/2，求导得到移位方程。μ>0 使其正定，抑制近奇异方向的大步。',r'\min_d\tfrac12\|r+Jd\|^2+\tfrac\mu2\|d\|^2\Rightarrow(J^TJ+\mu I)d=-J^Tr.','阻尼越大通常越保守，但必须结合真实目标验收。')])

setp('alm','固定罚系数的 ALM 为什么仍能逼近等式可行？','特例 f(x)=‖x−c‖²/2，约束 aᵀx=b，a≠0，ρ>0；每个子问题精确求解。','罚函数只加硬弹簧；ALM 还记住之前的约束误差，逐步把弹簧的平衡位置推到正确处。',[
('写子问题驻定条件','令 s=‖a‖²、δ=aᵀc−b。对增广拉格朗日函数求导。',r'0=x-c+\lambda a+\rho a(a^Tx-b),\qquad s=\|a\|^2>0.','乘子是历史补偿，不是每次清零的参数。'),
('先只求约束残差','左右乘 aᵀ 并用 r=aᵀx−b，可消去整个向量，得到一个标量方程。',r'r=\delta-s\lambda-\rho sr\Rightarrow r=\frac{\delta-s\lambda}{1+\rho s}.','高维约束误差在这个例子中缩成一维。'),
('恢复完整原始点','将 r 代回向量驻定关系，并合并 λ+ρr。',r'x^+=c-a\frac{\lambda+\rho\delta}{1+\rho s}.','每一轮图中的点都精确最小化当前子问题。'),
('罚函数为何需要增大 ρ','普通二次罚函数对应 λ=0，除非 δ=0 原无约束解已可行，否则有限 ρ 仍留非零残差。',r'r_{\rm penalty}=\delta/(1+\rho s),\quad\kappa(I+\rho aa^T)=1+\rho s\quad(n>1).','越来越硬的弹簧也使子问题越来越病态。'),
('推导乘子的误差递推','真实 KKT 乘子为 λ*=δ/s。用 λ⁺=λ+ρr 代入上式，并减 λ*。',r'\lambda^+=\frac{\lambda+\rho\delta}{1+\rho s},\quad\lambda^+-\lambda^*=\frac{\lambda-\lambda^*}{1+\rho s}.','固定 ρ 时已有严格小于 1 的收缩因子。'),
('推出可行性与原始收敛','乘子误差几何衰减，于是残差趋零。将极限乘子代入 x 公式得到等式投影点。',r'\lambda_k\to\delta/s,\quad r_k\to0,\quad x_k\to c-a\delta/s.','ALM 不是靠无限加硬，而是靠不断纠正中心。')])

setp('interior','中心路径、稳定根式与 2μ 对偶间隙','min x₂，约束 x₁+x₂=1、xᵢ≥0；障碍参数 μ>0。2μ 间隙只在精确中心构造的原始—对偶点成立。','障碍把边界推成墙；减小 μ 是逐步拆墙，而不是让一个不可行点穿墙。',[
('消去等式但保留严格可行域','令 t=x₂，则 x₁=1−t，严格可行等价于 0<t<1。',r'\phi_\mu(t)=t-\mu\log t-\mu\log(1-t),\quad0<t<1.','两面墙分别是 t=0 和 t=1。'),
('求导确认唯一中心','二阶导严格为正，且边界处函数趋无穷，所以内部存在唯一极小点。',r'\phi_\mu^{\prime}=1-\mu/t+\mu/(1-t),\quad\phi_\mu^{\prime\prime}=\mu/t^2+\mu/(1-t)^2>0.','只要 μ>0，中心始终在两堵墙之间。'),
('驻定式化成二次方程','将一阶导为零的等式乘 t(1−t)，该因子在域内严格正，不引入或漏掉合法根。',r't(1-t)-\mu(1-t)+\mu t=0\iff t^2-(1+2\mu)t+\mu=0.','先保留符号，再做代数，避免漏掉负号。'),
('选择内部根并有理化','两个根中只有减号根落在 (0,1)。乘共轭分母得到避免相近大数相减的稳定表达。',r't_\mu=\frac{1+2\mu-\sqrt{1+4\mu^2}}2=\frac{2\mu}{1+2\mu+\sqrt{1+4\mu^2}}.','稳定公式改变计算方式，不改变数学上的根。'),
('构造对偶可行点','令目标系数 c=(0,1)，对偶约束 c−y(1,1)=s≥0。中心的障碍驻定给出 sᵢ=μ/xᵢ，从而存在共同的 y。',r'c-y\mathbf1=s,\quad s_i=\mu/x_i>0,\quad x_is_i=\mu.','每个坐标都保留同样的互补乘积 μ。'),
('计算真实间隙','原始目标 cᵀx 与对偶目标 y 相减，利用 x₁+x₂=1 得到 xᵀs，再代入互补关系。',r'c^Tx-y=x^T(c-y\mathbf1)=x^Ts=2\mu.','不在中心时，不能把 2μ 直接标成当前点的间隙。'),
('取 μ 趋零的极限','稳定根式分母趋 2，因此 tμ→0，原始中心趋最优边界点，间隙也趋零。',r'\mu\downarrow0\Rightarrow t_\mu\to0,\quad(x_1,x_2)\to(1,0),\quad2\mu\to0.','中心可以无限接近边界，但有限 μ 不到达边界。')])

# Remaining chapters are appended below.
setp('prox','软阈值：零点来自次微分，不是数值截断','g(x)=λ|x|，τ>0，λ≥0；记阈值 a=τλ。多维 L₁ 情形逐坐标分离。','零点能用一整个斜率区间抵消拉力；超过这个区间后，解才开始离开零。',[
('先把尺度统一','邻近问题乘正数 τ 不改变最优点，得到平方距离加 a|x| 的问题。',r'\operatorname{prox}_{\tau g}(v)=\arg\min_x\left\{\tfrac12(x-v)^2+a|x|\right\},\quad a=\tau\lambda.','比较的是阈值 τλ，不应漏掉 λ。'),
('证明解存在且唯一','目标连续且随 |x| 趋无穷，因此达到最小值；平方项为 1-强凸，加凸绝对值后仍强凸。',r'\phi(x)=\tfrac12(x-v)^2+a|x|,\qquad0\in x-v+a\partial|x|.','不存在需要在多个候选最优点中随意选一个的歧义。'),
('假定正解并验证符号','x>0 时绝对值导数为 1，驻定给出 x=v−a；这个候选只有 v>a 时与正解假定一致。',r'x>0\Rightarrow0=x-v+a\Rightarrow x=v-a>0\iff v>a.','右侧解比输入向原点收缩 a。'),
('假定负解并验证符号','x<0 时绝对值导数为 −1，得到 x=v+a；合法条件为 v<−a。',r'x<0\Rightarrow0=x-v-a\Rightarrow x=v+a<0\iff v<-a.','左侧也是向原点收缩相同距离。'),
('在零点用区间而非导数','零点的次微分为 [−1,1]。驻定包含零当且仅当 v 落在 [−a,a]。',r'x=0\iff0\in-v+a[-1,1]\iff|v|\le a.','这里是整段输入都被映到同一个点。'),
('合并并核对边界','三个区域覆盖全部实数，在 v=±a 处公式一致且连续；a=0 时退化为恒等映射。',r'S_a(v)=\begin{cases}v-a,&v>a,\\0,&|v|\le a,\\v+a,&v<-a.\end{cases}','阈值区间端点不会引入跳跃。'),
('推广到向量 L₁','目标是各坐标独立项的和，所以每个坐标可单独取最优点，不需要联合迭代。',r'\operatorname{prox}_{\tau\lambda\|\cdot\|_1}(v)_i=S_{\tau\lambda}(v_i).','这与相关 Q 下直接阈值无正则最优解不同。')])
extra('prox','牢固非扩张与 Moreau 分解','g 适当、闭、凸，τ>0；所有点在有限维欧氏空间。','两个输入点经过同一个凸 prox，不仅不会被拉得更远，消去的部分还与保留的部分满足能量约束。',[
('写两个邻近最优条件','令 p=P(v)、q=P(w)。平方距离的梯度给出两个属于次微分的向量。',r'(v-p)/\tau\in\partial g(p),\quad(w-q)/\tau\in\partial g(q).','输入到输出的箭头就是一个缩放次梯度。'),
('证明次微分单调性','分别以 p、q 为支撑点写凸性不等式，随后相加，函数值抵消。',r'g(q)\ge g(p)+a^T(q-p),\quad g(p)\ge g(q)+b^T(p-q)\Rightarrow(a-b)^T(p-q)\ge0.','两个支撑斜率不能朝相反方向拉开。'),
('代入并移项','令 a=(v−p)/τ、b=(w−q)/τ。乘 τ 并整理，即得到牢固非扩张。',r'\|p-q\|^2\le(p-q)^T(v-w).','左侧是输出距离平方，右侧记录输入与输出方向的对齐。'),
('普通非扩张是推论','使用 Cauchy–Schwarz。当 p≠q 时除以其距离；相等时结论直接成立。',r'\|p-q\|^2\le\|p-q\|\|v-w\|\Rightarrow\|P(v)-P(w)\|\le\|v-w\|.','数值抽样可以检验，但上面的量词证明覆盖全部输入。'),
('用共轭交换次梯度','从 a=(v−p)/τ∈∂g(p)，Fenchel 等号及闭凸双共轭关系给 p∈∂g*(a)。',r'p\in\partial g^*(a),\quad a=(v-p)/\tau.','原空间保留的部分成为对偶空间的次梯度。'),
('辨认另一侧的邻近条件','将 p=v−τa 代入并整理，恰是 prox_{g*/τ}(v/τ) 的最优性条件。',r'0\in\partial g^*(a)+\tau(a-v/\tau)\Rightarrow v=\operatorname{prox}_{\tau g}(v)+\tau\operatorname{prox}_{g^*/\tau}(v/\tau).','软阈值留下的余量，正是盒投影的缩放。')],scene='nonexpansive')

setp('prox-gradient','三点不等式：邻近梯度的每一步到底保证什么？','f 凸、可微且梯度 L-Lipschitz；g 适当闭凸；F=f+g 有最优解。以下固定 τ=1/L 且精确求 prox。','用一个盖住真实目标的碗做替身；在替身碗里降下去，就能给真实目标建立距离账本。',[
('从积分证明下降引理','令 d=z−y，沿线积分梯度增量；Lipschitz 条件把内积绝对值压在 Lt‖d‖² 内。',r'f(z)-f(y)-\nabla f(y)^Td=\int_0^1[\nabla f(y+td)-\nabla f(y)]^Td\,dt\le\tfrac L2\|d\|^2.','橙色二次模型从上面罩住光滑函数。'),
('定义强凸代理目标','保留 g，不把尖点线性化；加入 L/2 的平方距离项。',r'Q_L(z;y)=f(y)+\nabla f(y)^T(z-y)+\tfrac L2\|z-y\|^2+g(z),\quad F(z)\le Q_L(z;y).','上界的最小点容易求，并且结构性非光滑仍被精确保留。'),
('配方得到邻近更新','与 z 无关的常数不改变最优点，线性项与平方项合并成移位平方。',r'p=\arg\min_zQ_L(z;y)=\operatorname{prox}_{g/L}(y-\nabla f(y)/L).','先走梯度步，再由 prox 修正。'),
('强凸性给出最小值余量','代理目标为 L-强凸，且 0∈∂Q_L(p;y)。在 p 处应用强凸支撑式。',r'Q_L(p;y)+\tfrac L2\|u-p\|^2\le Q_L(u;y)\quad\forall u.','不只知道 p 更低，还知道至少省下一个距离平方。'),
('凸性给出另一侧上界','f 的切平面是下界，所以 f(y)+∇f(y)ᵀ(u−y)≤f(u)。代入代理目标。',r'Q_L(u;y)\le F(u)+\tfrac L2\|u-y\|^2.','同一个光滑函数被一阶下界和二阶上界夹住。'),
('合并成关键三点不等式','先用 F(p)≤Q_L(p;y)，再接上前两步，移项得到完整结论。',r'F(p)-F(u)\le\tfrac L2\bigl(\|u-y\|^2-\|u-p\|^2\bigr).','这里的三个点是基点 y、新点 p 和任意比较点 u。'),
('比较旧点得到单调下降','普通 PG 取 y=xₖ、p=xₖ₊₁，再令 u=xₖ。第一项距离为零。',r'F(x_{k+1})\le F(x_k)-\tfrac L2\|x_{k+1}-x_k\|^2.','FISTA 的 y 不是 xₖ，不能用这一行声称它单调。')])
extra('prox-gradient','PG 的 O(1/k) 目标界：逐项抵消的全过程','沿用三点不等式假设，xₖ₊₁=P_L(xₖ)，k≥0；最优点 x* 存在。','每次减少一点到最优点的距离平方；把所有减少累加，最多只有初始距离那么多。',[
('将比较点设为最优点','三点不等式中的 u=x*，基点是 xⱼ，新点是 xⱼ₊₁。',r'F(x_{j+1})-F^*\le\tfrac L2(\|x_j-x^*\|^2-\|x_{j+1}-x^*\|^2).','每步间隙都能由相邻距离差支付。'),
('从 0 加到 k−1','所有中间距离出现一次正号、一次负号，完全抵消。',r'\sum_{j=0}^{k-1}(F(x_{j+1})-F^*)\le\tfrac L2(\|x_0-x^*\|^2-\|x_k-x^*\|^2).','这就是望远镜求和，不是省略号掩盖的推理。'),
('去掉非正末项','距离平方非负，所以减去末项只会使右边更小；去掉它仍给有效上界。',r'\sum_{j=0}^{k-1}(F(x_{j+1})-F^*)\le LD^2/2,\quad D=\|x_0-x^*\|.','上界只取决于初始距离与 L。'),
('用单调性选最后一点','PG 目标单调，因此前 k 个新点的间隙均不小于第 k 点的间隙。',r'k(F(x_k)-F^*)\le\sum_{j=0}^{k-1}(F(x_{j+1})-F^*).','没有单调性时，这一步只能换成最好值或平均值。'),
('除以迭代次数','两条上界合并，k≥1 时可除以 k。该不等式是明确常数的界，不是经验拟合。',r'F(x_k)-F^*\le\frac{LD^2}{2k}.','实验曲线可以低于这条界很多，仍完全符合定理。')],scene='rates')

setp('acceleration','FISTA 的 O(1/k²)：从外推几何到势函数抵消','f 凸且 L 光滑，g 适当闭凸，精确 prox，存在 x*，固定步长 1/L。算法使用 q₀=1、y₀=x₀ 的经典平方根递推。','动量不是免费能量；把目标间隙乘上逐渐变大的权重，再配一个“校正位置”的距离，才能看见总账递减。',[
('先锁定实际算法与编号','每轮先在 yₖ 求梯度和 prox，随后更新 q 和外推 y。x 是真实迭代点，y 是梯度评估点。',r'\begin{aligned}x_{k+1}&=P_L(y_k),\\q_{k+1}&=(1+\sqrt{1+4q_k^2})/2,\\y_{k+1}&=x_{k+1}+\frac{q_k-1}{q_{k+1}}(x_{k+1}-x_k).\end{aligned}','把图中的外推点与新点分开，不能在错误位置求梯度。'),
('改记权重并写关键恒等式','对第 k 个新点令 aₖ=qₖ₋₁，k≥1。平方根递推两边平方移项，得到精确关系。',r'a_1=1,\quad a_k^2-a_k=a_{k-1}^2\ (k\ge2),\quad y_{k-1}=x_{k-1}+\frac{a_{k-1}-1}{a_k}(x_{k-1}-x_{k-2}).','这个权重恒等式将负责消掉上一轮目标间隙。'),
('选一个特殊比较点','用 xₖ₋₁ 与 x* 的凸组合 zₖ 作为三点不等式的比较点。aₖ≥1 保证系数合法。',r'z_k=(1-1/a_k)x_{k-1}+x^*/a_k,\quad F(z_k)-F^*\le(1-1/a_k)\Delta_{k-1}.','比较点不是算法需要知道的输入；只用于证明。'),
('应用三点不等式并放大','在 yₖ₋₁ 处做 prox 得到 xₖ。以 zₖ 为比较点，代入上一步并乘 aₖ²。',r'a_k^2\Delta_k-(a_k^2-a_k)\Delta_{k-1}\le\tfrac L2\left(\|a_k(z_k-y_{k-1})\|^2-\|a_k(z_k-x_k)\|^2\right).','两条距离被乘上权重，形成可望远镜消去的形状。'),
('定义校正位置并逐项辨认','令 wₖ=aₖxₖ−(aₖ−1)xₖ₋₁−x*。用外推式展开左侧比较距离，可得它恰好等于上一轮的 w。',r'w_k=a_kx_k-(a_k-1)x_{k-1}-x^*,\quad a_k(z_k-x_k)=-w_k,\quad a_k(z_k-y_{k-1})=-w_{k-1}.','w 不是另一条实际算法轨迹，而是证明里的校正坐标。'),
('得到单调势函数','使用 aₖ²−aₖ=aₖ₋₁²，把目标权重与距离平方合并，得到 Eₖ≤Eₖ₋₁。',r'E_k:=a_k^2\Delta_k+\tfrac L2\|w_k\|^2\le a_{k-1}^2\Delta_{k-1}+\tfrac L2\|w_{k-1}\|^2=E_{k-1}.','F 本身可以上升，但这个组合账本不能上升。'),
('单独核对第一步','a₁=1、w₁=x₁−x*。直接对第一次 PG 更新用三点不等式，就得到起始能量界。',r'\Delta_1+\tfrac L2\|x_1-x^*\|^2\le\tfrac L2\|x_0-x^*\|^2\Rightarrow E_1\le LD^2/2.','不能把没有定义的 x₋₁、w₀ 塞进递推。'),
('证明权重至少线性增长','根式满足 √(1+4a²)≥2a，因此 aₖ₊₁≥aₖ+1/2。由 a₁=1 归纳得到下界。',r'a_{k+1}\ge a_k+\tfrac12\Rightarrow a_k\ge(k+1)/2.','目标权重 aₖ² 至少按 k² 增长。'),
('丢掉非负距离项并求最终界','由势函数单调和初始界，aₖ²Δₖ≤LD²/2；再使用权重下界。',r'F(x_k)-F^*\le\frac{LD^2}{2a_k^2}\le\frac{2LD^2}{(k+1)^2},\qquad k\ge1.','收敛阶来自能量与权重，不是把轨迹画成一条 k⁻² 曲线。')])

setp('envelope','log-sum-exp 的误差界与 |x| 的 Moreau 包络','μ>0；LSE 先对有限个实数 aᵢ 讨论；Moreau 例子取 g(x)=|x|。','一种平滑从上方包住尖点，另一种从下方磨圆尖点；更准确的平滑通常有更大的曲率。',[
('先减掉最大值','令 m=maxᵢaᵢ，提取 exp(m/μ)。这一代数恒等式也是数值防溢出的实现依据。',r'\mu\log\sum_i e^{a_i/\mu}=m+\mu\log\sum_i e^{(a_i-m)/\mu}.','最大的指数变成 1，其余都在 (0,1] 内。'),
('夹住剩余指数和','至少有一项等于 1，每项都不超过 1，所以总和位于 [1,n]。log 单调递增。',r'1\le\sum_i e^{(a_i-m)/\mu}\le n\Rightarrow m\le\operatorname{LSE}_\mu(a)\le m+\mu\log n.','上方平滑的竖直误差最多 μ log n。'),
('计算两项 max 的导数','取 a=(x,−x)，求导后化成 tanh；再求导得到最大曲率为 1/μ。',r'f_\mu^{\prime}(x)=\tanh(x/\mu),\quad f_\mu^{\prime\prime}(x)=\frac1\mu(1-\tanh^2(x/\mu))\le1/\mu.','μ 越小，圆角越尖、曲率越大。'),
('Moreau 先求最小点','包络是邻近子问题的最优值。对 |x|，最小点由软阈值给出。',r'e_\mu|x|=\min_z\{|z|+(z-x)^2/(2\mu)\},\qquad z^*=S_\mu(x).','此处做的是最小化，不是指数平均。'),
('把两个区域分别代回','|x|≤μ 时 z*=0；|x|>μ 时 z*=x−μ sign(x)，分别代回平方项。',r'e_\mu|x|=\begin{cases}x^2/(2\mu),&|x|\le\mu,\\|x|-\mu/2,&|x|>\mu.\end{cases}','尖点附近是二次碗，远处是向下平移的直线。'),
('验证拼接处一阶连续','内部导数为 x/μ，外部为 sign(x)；在 ±μ 两侧均匹配。也可统一写成输入减邻近点的形式。',r'(e_\mu|\cdot|)^{\prime}(x)=\frac{x-S_\mu(x)}\mu=\operatorname{clip}(x/\mu,-1,1).','曲线和切线都接上了，但二阶导数可以跳变。'),
('说明偏差方向与尺度','取 z=x 就得到 eμ|x|≤|x|。分段公式进一步表明差值不超过 μ/2。',r'0\le|x|-e_\mu|x|\le\mu/2.','图中 LSE 在上、Moreau 在下，不能混成同一种近似。')])

setp('ppa','PPA 的下降、距离收缩与收敛','F 适当闭凸且有最优点，τ>0 固定，每个邻近子问题精确求解，有限维欧氏空间。','PPA 用新点处的斜率决定一步；它像隐式刹车，整个目标都进入了制动器。',[
('写邻近问题及最优条件','平方项使子问题强凸并有唯一解；最优性在新点上成立。',r'x_{k+1}=\arg\min_z\{F(z)+\|z-x_k\|^2/(2\tau)\},\quad(x_k-x_{k+1})/\tau\in\partial F(x_{k+1}).','与显式梯度法相比，斜率评估点移到了新点。'),
('比较旧点得到下降','旧点是合法候选，其距离代价为零。新点既然最优，代理目标不可能更大。',r'F(x_{k+1})+\|x_{k+1}-x_k\|^2/(2\tau)\le F(x_k).','较长的步必须付出足够的目标下降。'),
('用最优点作支撑比较','在新点处用已知次梯度写支撑不等式，并移项。',r'F(x_{k+1})-F^*\le\tau^{-1}(x_k-x_{k+1})^T(x_{k+1}-x^*).','新点离最优点的方向与这一步方向联系起来。'),
('展开内积成三个距离','用 2aᵀb=‖a+b‖²−‖a‖²−‖b‖²。',r'2\tau(F(x_{k+1})-F^*)\le\|x_k-x^*\|^2-\|x_{k+1}-x^*\|^2-\|x_{k+1}-x_k\|^2.','每次不仅目标变好，到每个最优解的距离也不增加。'),
('求和控制步长与残差','目标间隙非负，累加后步长平方总和有界，所以步差趋零；固定 τ 时次梯度残差也趋零。',r'\sum_k\|x_{k+1}-x_k\|^2\le\|x_0-x^*\|^2,\quad(x_k-x_{k+1})/\tau\to0.','距离预算排除了永远大幅来回跳动。'),
('从子列到整列','距离有界使迭代有聚点；闭凸次微分图闭且残差趋零，聚点为最优点。再以该聚点作比较，距离非增且某子列趋零，故整列趋零。',r'x_{k_j}\to\bar x,\quad0\in\partial F(\bar x),\quad\|x_k-\bar x\|\downarrow0.','证明需要有限维有界序列存在收敛子列；不是只看目标曲线。'),
('本例子问题如何计算','把二次损失与距离项合并，常数项去掉，得到新的 LASSO 二次矩阵与线性项。',r'Q_{\rm sub}=Q+I/\tau,\qquad b_{\rm sub}=b+x_k/\tau.','外层一步通常比一次软阈值昂贵，比较成本时必须记账。')])

setp('bcd','坐标软阈值与循环坐标下降的收敛','Q 对称正定，λ≥0，循环更新每个坐标且精确最小化；目标为二次 LASSO。','每次只允许沿一条坐标轴移动；耦合越强，后一次移动越可能补偿前一次。',[
('把当前坐标的项单独拿出','令 z 替代 xᵢ，其他坐标固定。利用 Q 对称，交叉项合并成一个线性系数。',r'\phi_i(z)=\tfrac12Q_{ii}z^2-c_i z+\lambda|z|+\text{常数},\quad c_i=b_i-\sum_{j\ne i}Q_{ij}x_j.','其他坐标通过 cᵢ 影响这一小步。'),
('完成平方并归一化','Qᵢᵢ>0，可除以它而不改变最优点。',r'\phi_i(z)=\tfrac12Q_{ii}(z-c_i/Q_{ii})^2+\lambda|z|+\text{常数}.','同一个软阈值，输入与阈值都要除以局部曲率。'),
('使用已证明的软阈值','应用标量 prox 公式，注意 S 的正齐次缩放。',r'x_i^+=S_{\lambda/Q_{ii}}(c_i/Q_{ii})=S_\lambda(c_i)/Q_{ii}.','只改一个坐标，不允许同时重算其他坐标。'),
('强凸性定量证明下降','一维目标 Qᵢᵢ-强凸，精确最小点的支撑不等式给出下降至少是步差平方的一半曲率。',r'F(x)-F(x^+)\ge\tfrac12Q_{ii}(x_i-x_i^+)^2\ge\tfrac\mu2\|x-x^+\|^2,\quad\mu=\lambda_{\min}(Q)>0.','这说明为什么单步目标必须不升。'),
('得到有界性和步差趋零','正定二次项保证有界子水平集；下降总量有限使所有子步的位移平方可求和，从而子步位移趋零。',r'\sum_k\|x^{k+1}-x^k\|^2\le2(F(x^0)-F^*)/\mu<\infty.','一轮中各坐标访问的时间不同，但它们之间的位移越来越小。'),
('极限满足每个坐标条件','取轮首点的收敛子列。每轮只有有限 n 个子步，故该轮所有中间点趋同一极限；各坐标最优性条件通过闭性传到极限。',r'0\in(Q\bar x-b)_i+\lambda\partial|\bar x_i|\quad\forall i\Rightarrow0\in Q\bar x-b+\lambda\partial\|\bar x\|_1.','这里使用了可分离 L₁ 结构，不能推广到任意非凸多块问题。'),
('唯一聚点推出整列收敛','凸最优性使每个聚点都是全局最优，严格凸性又使最优点唯一。有界序列若存在远离该点的子列，会产生第二个聚点，矛盾。',r'x^k\to x^*,\qquad x^*\text{ 为唯一 LASSO 最优点。}','有限实验只能验证实例；完整结论来自上述结构。')])

setp('primal-dual','L₁ 的鞍点改写、PDHG 更新与耦合步长条件','目标 f(x)+λ‖x‖₁，f 为正定二次函数；本实验 K=I、外推系数为 1。步长不等式是标准充分条件，不是必要条件。','一个变量找位置，另一个在盒中找支撑斜率；两边轮流反馈，因此步长不能各管各的。',[
('把绝对值写成最大支撑','对每个坐标，|yᵢ|≤λ 时 yᵢxᵢ≤λ|xᵢ|；取 yᵢ=λ sign(xᵢ) 实现等号。',r'\lambda\|x\|_1=\max_{\|y\|_\infty\le\lambda}y^Tx.','盒约束限制了惩罚能施加多大的斜率。'),
('得到鞍点表达而不交换次序','逐个 x 的恒等式可直接代入最小化；此处无须预先假定 min 与 max 可以交换。',r'\min_x f(x)+\lambda\|x\|_1=\min_x\max_{y\in B_\infty(\lambda)}[f(x)+y^Tx].','写成 min-max 与声称强对偶是不同步骤。'),
('对偶步是受约束的上升','对 y 最大化线性耦合减平方距离，完成平方后成为盒投影。',r'y^{k+1}=\arg\max_{y\in B}\{\langle y,\bar x^k\rangle-\|y-y^k\|^2/(2\sigma)\}=\Pi_B(y^k+\sigma\bar x^k).','箭头先走向外推位置，再被盒边界截住。'),
('原始步是一个二次 prox','固定新对偶变量，最小化 f(x)+⟨yₖ₊₁,x⟩+‖x−xₖ‖²/(2τ)，求导整理。',r'(I+\tau Q)x^{k+1}=x^k-\tau y^{k+1}+\tau b.','这里使用新 y，不是旧 y。'),
('外推改变下一次反馈位置','规定 θ=1，得到下一次对偶梯度用的外推点；它是算法状态的一部分。',r'\bar x^{k+1}=2x^{k+1}-x^k.','外推不等于又做了一次 prox。'),
('为什么步长要一起看','一般 K 的耦合二次型有一个交叉项。令 a=‖u‖/√τ、b=‖v‖/√σ，用 Cauchy–Schwarz。',r'\frac{\|u\|^2}{\tau}+\frac{\|v\|^2}{\sigma}-2\langle Ku,v\rangle\ge a^2+b^2-2\sqrt{\tau\sigma}\|K\|ab.','耦合可能吃掉两边各自的正距离预算。'),
('充分步长保留正余量','当 c=√(τσ)‖K‖<1 时，右边至少 (1−c)(a²+b²)，因此该度量正定。完整一般 PDHG 收敛定理另见原文；本段证明的是这一关键度量条件。',r'\tau\sigma\|K\|^2<1\Rightarrow\frac{\|u\|^2}{\tau}+\frac{\|v\|^2}{\sigma}-2\langle Ku,v\rangle>0\quad((u,v)\ne0).','越过标准阈值只代表这项保证失效，不代表每个实例必然发散。')])
extra('primal-dual','等式二次模型的对偶梯度：残差就是导数','f(x)=‖x−c‖²/2，aᵀx=b，a≠0。乘子不受符号限制。','把约束误差当反馈信号：残差为正便抬高乘子，压低下一轮的约束值。',[
('固定乘子求原始极小','对拉格朗日函数求 x 导数为零。',r'x(\lambda)=c-\lambda a.','每一个乘子对应一个精确恢复的原始点。'),
('代回得到对偶抛物线','令 δ=aᵀc−b、s=‖a‖²。分别代回距离项与乘子项，再合并。',r'q(\lambda)=\lambda\delta-\tfrac s2\lambda^2.','对偶函数开口向下，最大点容易识别。'),
('导数就是约束残差','直接求导，结果与 aᵀx(λ)−b 完全一致。',r'q^{\prime}(\lambda)=\delta-s\lambda=a^Tx(\lambda)-b.','这不是巧选的经验控制律，而是对偶梯度。'),
('推导上升法的精确递推','采用 λ⁺=λ+αq′(λ)，再减去 λ*=δ/s。',r'\lambda^+-\lambda^*=(1-\alpha s)(\lambda-\lambda^*).','反馈太大同样会来回过冲。'),
('给出稳定范围','标量因子绝对值小于 1，当且仅当 0<α<2/s；因此这个范围内乘子和恢复点均收敛。',r'0<\alpha<2/s\Rightarrow\lambda_k\to\lambda^*,\quad x(\lambda_k)\to c-a\delta/s.','这里只证明该解析模型，不冒充一般非光滑对偶理论。')],scene='dual')

setp('admm','ADMM 的三个子步与两种残差','问题 min f(x)+g(z)，约束 x=z；f(x)=xᵀQx/2−bᵀx，g(z)=λ‖z‖₁，Q 正定，ρ>0。u=y/ρ。','x 追求拟合，z 追求稀疏，u 保存分歧；不是三个点一起朝同一个目标盲目下降。',[
('先分裂但不改变原问题','只要最终满足 x=z，两个块的目标之和就等于原始目标；不满足一致性时不能把分裂值当作原问题可行值。',r'\min_{x=z}f(x)+g(z).','两个变量的分离是计算策略，不是放宽最后的约束。'),
('完成乘子项的平方','把 yᵀ(x−z)+ρ‖x−z‖²/2 配方，定义缩放乘子 u=y/ρ。',r'\mathcal L_\rho=f(x)+g(z)+\tfrac\rho2\|x-z+u\|^2-\tfrac\rho2\|u\|^2.','u 是缩放后的历史力，不是另一个原始变量。'),
('x 步：固定旧 z 和旧 u','对 x 的二次子问题求导并移项，得到一个正定线性系统。',r'(Q+\rho I)x^{k+1}=b+\rho(z^k-u^k).','此时 z、u 都尚未更新。'),
('z 步：使用新 x、旧 u','z 子问题以 xₖ₊₁+uₖ 为邻近输入，阈值为 λ/ρ。',r'z^{k+1}=S_{\lambda/\rho}(x^{k+1}+u^k).','软阈值可能一下让某些坐标为零。'),
('u 步：累积当前不一致','用新 x 与新 z 的差更新缩放乘子，等价于非缩放乘子加 ρ 倍残差。',r'r^{k+1}=x^{k+1}-z^{k+1},\quad u^{k+1}=u^k+r^{k+1},\quad y^{k+1}=y^k+\rho r^{k+1}.','只有到这里，一整轮才算完成。'),
('从子问题条件读取驻定误差','把乘子更新代回 x 和 z 的最优条件，得到精确的两个包含式。',r'0\in\partial f(x^{k+1})+y^{k+1}+\rho(z^{k+1}-z^k),\quad y^{k+1}\in\partial g(z^{k+1}).','第二式已经满足；第一式还多了一项 z 的变化。'),
('定义两种残差的意义','r 测量可行性，s 测量剩余的 x 站定误差（符号约定可相反，范数相同）。两个都小才支持近似 KKT。',r'r^{k+1}=x^{k+1}-z^{k+1},\quad s^{k+1}=\rho(z^{k+1}-z^k).','只看 x≈z，仍可能在错误位置达成一致。')])
extra('admm','两块一致性 ADMM 的收敛：完整能量证明','有限维；f、g 适当闭凸，存在鞍点 (x*,z*,y*) 且 x*=z*；每轮子问题存在并精确求解，ρ>0 固定。以下 k≥1，以保证 yᵏ∈∂g(zᵏ)。','残差与变量变化的平方都从同一个有限能量预算扣除；预算有限，就不能永远有明显分歧。',[
('把最优解也写成次梯度关系','鞍点条件给出 f 的支撑斜率 −y* 与 g 的支撑斜率 y*，且两个原始块相等。',r'-y^*\in\partial f(x^*),\quad y^*\in\partial g(z^*),\quad x^*=z^*.','两块在最优处承受大小相等、方向相反的力。'),
('用次微分单调性比较新点与解','令 r=x⁺−z⁺、d=z⁺−z，使用前一证明的子问题条件，各自写单调性再相加。',r'\langle r,y^+-y^*\rangle+\rho\langle z^+-z^*,d\rangle+\rho\langle r,d\rangle\le0.','原始不一致、乘子误差和 z 位移第一次出现在同一个式子里。'),
('解释交叉项为何非负','从第二轮起，y∈∂g(z) 且 y⁺∈∂g(z⁺)。单调性及 y⁺−y=ρr 给出交叉项符号。',r'\langle d,y^+-y\rangle=\rho\langle d,r\rangle\ge0.','这一步不能在任意不一致的初始 y、z 上直接假定。'),
('定义总能量','同时测量对偶误差与 z 误差，权重互为 ρ 与 1/ρ。',r'V_k=\rho^{-1}\|y^k-y^*\|^2+\rho\|z^k-z^*\|^2\ge0.','ρ 只重新分配两种误差的计价单位。'),
('逐项展开能量差','使用 y=y⁺−ρr、z=z⁺−d，把两个平方差完整展开。',r'V_k-V_{k+1}=-2\langle r,y^+-y^*\rangle-2\rho\langle d,z^+-z^*\rangle+\rho\|r\|^2+\rho\|d\|^2.','交叉项不是凭空消失，而是在下一步用单调性控制。'),
('得到每轮的能量下降','前两步的内积和不等式给出前两项至少为 2ρ⟨r,d⟩≥0。',r'V_k-V_{k+1}\ge\rho\|r^{k+1}\|^2+\rho\|z^{k+1}-z^k\|^2.','能量下降至少支付两种残差的平方成本。'),
('望远镜求和得到残差趋零','从 k=1 求和，V 非负且不增加，故右侧非负级数有限；各项必趋零。',r'\sum_{k\ge1}(\|r^{k+1}\|^2+\|z^{k+1}-z^k\|^2)\le V_1/\rho<\infty.','因此 r→0，s=ρd→0，而不是只在图上“看起来稳定”。'),
('有界性、聚点与 KKT','V 有界使 y、z 有界，r→0 使 x 也有界。取共同收敛子列，利用闭凸次微分图闭，将两个子问题关系传到极限。',r'\bar x=\bar z,\quad-\bar y\in\partial f(\bar x),\quad\bar y\in\partial g(\bar z).','有限维和闭性把残差趋零变成真正的最优聚点。'),
('从一个聚点推广到整列','能量不等式对任意鞍点成立。以该聚点为参照，能量有一条子列趋零，又非增，故整列趋零；x=z+r 同时收敛。',r'y^k\to\bar y,\quad z^k\to\bar z,\quad x^k\to\bar x.','这是 x=z 一致性形式的结论，不无条件扩展到一般多块形式。'),
('最后夹住目标值','在鞍点写支撑得到下界，在新点写支撑得到上界；有界性与 r,d→0 使两边都趋零。',r'-\langle y^*,r\rangle\le f(x^+)+g(z^+)-F^*\le-\langle y^+,r\rangle-\rho\langle d,x^+-x^*\rangle\to0.','即使不预先假设目标连续，也能得到目标收敛。')],scene='admm-energy')

setp('stochastic','无偏、批量方差与 SVRG 的抵消机制','有限和目标 F=(1/n)Σfᵢ；每次均匀独立有放回抽样。条件期望以当前点和历史已固定为前提。','噪声不是神秘的随机抖动，而是每个样本梯度与完整梯度的差；SVRG 试图用同一份样本噪声相减。',[
('直接求期望证明无偏','每个样本以 1/n 概率被选中。期望就是有限平均，与 F 的梯度一致。',r'\mathbb E_i[\nabla f_i(x)]=\frac1n\sum_i\nabla f_i(x)=\nabla F(x).','不是每次都准确，而是条件平均准确。'),
('把估计写成真值加噪声','定义 ξᵢ=∇fᵢ−∇F，则均值为零，方差用欧氏平方范数的期望表示。',r'g_i=\nabla F(x)+\xi_i,\quad\mathbb E\xi_i=0,\quad\mathbb E\|\xi_i\|^2=\sigma_x^2.','图中每条样本箭头相对均值的偏差就是噪声。'),
('独立批量为什么降低方差','B 个独立噪声相加时，交叉内积期望因独立和零均值而为零，留下 B 个方差项。',r'\mathbb E\left\|\frac1B\sum_{j=1}^B\xi_j\right\|^2=\frac1{B^2}\sum_{j=1}^B\mathbb E\|\xi_j\|^2=\sigma_x^2/B.','有放回抽 B=n 个样本，不代表恰好遍历全部样本。'),
('常数步长为什么留下噪声成本','对 L 光滑的 F 使用下降引理，再对当前样本取条件期望。梯度噪声均值为零，但平方项中的方差不会消失。',r'\mathbb E[F(x-\alpha g_i)\mid x]\le F(x)-\alpha(1-L\alpha/2)\|\nabla F(x)\|^2+\tfrac{L\alpha^2}{2}\sigma_x^2.','靠近最优点时，下降信号变小，噪声项仍可能存在。'),
('构造 SVRG 并核对无偏','同一样本在当前点和快照点都求梯度，再加快照完整梯度；期望中的快照项精确抵消。',r'v_i=\nabla f_i(x)-\nabla f_i(\tilde x)+\nabla F(\tilde x),\quad\mathbb E v_i=\nabla F(x).','必须使用同一个样本 i 才有直接的差分抵消。'),
('推导一个方差上界','若每个样本梯度 Lᵢ-Lipschitz，方差不超过相对任意确定向量的二阶矩。取向量 ∇F(快照)。',r'\mathbb E\|v_i-\nabla F(x)\|^2\le\frac1n\sum_i\|\nabla f_i(x)-\nabla f_i(\tilde x)\|^2\le\frac1n\sum_i L_i^2\|x-\tilde x\|^2.','当前点等于快照时，方差恰好为零；远离快照后可能重新增大。')])

setp('manifold','球面的切空间、梯度投影与回缩','单位球面 ‖x‖=1，欧氏诱导度量；Rayleigh 例子 A 为实对称矩阵。','先把指向球外的力去掉，只留下贴着球面的力；迈出切向小步后再回到球面。',[
('对约束沿曲线求导','设球面曲线 γ(t)，γ(0)=x、γ′(0)=v。对 γᵀγ=1 求导。',r'2x^Tv=0\Rightarrow T_x\mathbb S^{n-1}=\{v:x^Tv=0\}.','半径与切线垂直来自约束的导数。'),
('找保留方向导数的切向向量','欧氏梯度减去沿 x 的分量，得到切向向量；它与任何切向 v 的内积仍等于原梯度内积。',r'g_R=(I-xx^T)\nabla f(x),\quad x^Tg_R=0,\quad v^Tg_R=v^T\nabla f(x).','删掉法向分量不会改变合法方向上的一阶变化。'),
('证明它是球面最陡方向','对单位切向 v，Cauchy–Schwarz 给出方向导数下界，且负单位黎曼梯度达到它。',r'v^Tg_R\ge-\|g_R\|,\quad v=-g_R/\|g_R\|\quad(g_R\ne0).','“最陡”依赖切空间和选定度量。'),
('构造归一化回缩','令 Rₓ(η)=(x+η)/‖x+η‖。η 与 x 垂直，因此分母平方是 1+‖η‖²，永不为零。',r'R_x(\eta)=\frac{x+\eta}{\sqrt{1+\|\eta\|^2}},\quad\|R_x(\eta)\|=1.','回缩保证新点可行，而切向向量本身不在球面上。'),
('验证一阶正确性','Rₓ(0)=x。对 t 求导，在零点归一化因子的导数为零，故导数恰好为 η。',r'\left.\frac{d}{dt}R_x(t\eta)\right|_{t=0}=\eta,\quad\left.\frac{d}{d\alpha}f(R_x(-\alpha g_R))\right|_{\alpha=0}=-\|g_R\|^2.','因此足够小的回缩步确实下降。'),
('代入 Rayleigh 目标','欧氏梯度为 2Ax；投影后减去 2(xᵀAx)x。驻定等价于 x 是一个特征向量。',r'g_R=2(Ax-(x^TAx)x),\quad g_R=0\iff Ax=(x^TAx)x.','不是每个特征向量都对应最小特征值。'),
('用谱展开辨认全局最小','令 x=Σcᵢvᵢ、Σcᵢ²=1，Rayleigh 商是特征值的凸组合，所以最小值为最小特征值。',r'x^TAx=\sum_i\lambda_i c_i^2\ge\lambda_{\min}(A).','A=I 时所有点都同样好，切向力应处处为零。')])

setp('semismooth','分段残差、广义 Jacobian 与局部超线性收敛','t>0，Q 正定，λ≥0。局部理论要求所选广义 Jacobian 在解邻域内非奇异且逆一致有界，并满足半光滑余项条件；完整步与保护步分开。','尖点把空间切成不同线性片区；牛顿不必抹平尖点，只需知道当前片区如何把输入变成残差。',[
('从最优条件得到不动点','prox 的最优条件告诉我们：x=prox_{tλ‖·‖₁}(x−t(Qx−b)) 等价于原问题的次梯度平衡。',r'R(x)=x-S_{t\lambda}(x-t(Qx-b)),\quad R(x)=0\iff0\in Qx-b+\lambda\partial\|x\|_1.','阈值一定是 tλ，而不是 t。'),
('逐片区求软阈值导数','令 v=x−t(Qx−b)。阈值外导数为 1，阈值内为 0，边界可以选择区间 [0,1] 中的广义导数。',r'D_{ii}=1\ (|v_i|>t\lambda),\quad D_{ii}=0\ (|v_i|<t\lambda),\quad D_{ii}\in[0,1]\ (|v_i|=t\lambda).','活动掩码改变的是局部线性映射，不只是颜色。'),
('应用链式法则','v 对 x 的 Jacobian 为 I−tQ。残差等于 x 减软阈值，所以得到 J。',r'J=I-D(I-tQ)=I-D+tDQ.','实验在阈值边界明确选 Dᵢᵢ=0。'),
('解释二值掩码下的可逆性','按非活动、活动坐标重排，J 是块下三角：非活动行是单位阵，活动主块是 tQ_AA。Q 正定使主子矩阵正定。',r'J=\begin{pmatrix}I&0\\tQ_{AI}&tQ_{AA}\end{pmatrix},\quad Q_{AA}\succ0\Rightarrow J\text{ 可逆。}','这项保证依赖 Q 正定和当前残差结构。'),
('写半光滑性的正确余项','令 e=x−x*，选 J∈∂R(x)。半光滑性要求线性余项是 o(‖e‖)，强半光滑时为 O(‖e‖²)。',r'R(x)-R(x^*)-Je=o(\|e\|);\quad\text{强半光滑时 }O(\|e\|^2).','不是宣称经典导数在尖点存在。'),
('推导完整牛顿步误差','R(x*)=0，完整步 x⁺=x−J⁻¹R(x)，于是误差等于负的逆矩阵乘线性余项。',r'e^+=-J^{-1}[R(x)-R(x^*)-Je].','代数形式与光滑牛顿相似，但余项的定义不同。'),
('由有界逆得到速率','若 ‖J⁻¹‖≤M，直接取范数；初值足够近保证迭代留在假设邻域。',r'\|e^+\|=o(\|e\|),\quad\text{强半光滑时 }\|e^+\|=O(\|e\|^2).','超线性或二次结论不等于任意远处初值都收敛。'),
('活动片区稳定时的特例','LASSO 残差在固定片区内仿射。若当前点、根和完整步都处于同一有效片区，线性余项为零，精确牛顿一次到根。',r'R(x)=Jx+c\Rightarrow x-J^{-1}R(x)=-J^{-1}c=x^*.','跨片区或回溯缩步时，不能无条件声称一步终止。')])

setp('geometry-algorithms','Frank–Wolfe 的证书与熵镜像的闭式更新','C 为概率单纯形；FW 的间隙证书要求 f 凸可微。镜像步初值各分量严格正，步长 α>0，方向 g 有限。','一个算法找最有利的顶点后混合，另一个重新加权所有坐标；可行性来自不同机制。',[
('线性目标在顶点取最小','对单纯形中任意 s，gᵀs 是各 gᵢ 的加权平均，不能小于最小分量；在最小分量对应顶点取等。',r'g^Ts=\sum_i s_i g_i\ge\min_i g_i,\quad s=e_j,\ j\in\arg\min_i g_i.','FW 只需要线性预言机，不必求欧氏投影。'),
('凸组合自动保留可行','当前点与顶点都在凸集内，0≤γ≤1 时新点仍非负且和为 1。',r'x^+=(1-\gamma)x+\gamma e_j,\quad x^+\ge0,\quad\mathbf1^Tx^+=1.','轨迹沿指向顶点的线段移动。'),
('证明 FW gap 是目标上界','凸性给 f(x)−f*≤gᵀ(x−x*)；线性最优性给 gᵀs≤gᵀx*，合并即可。',r'f(x)-f^*\le g^T(x-x^*)\le g^T(x-s)=G_{\rm FW}(x).','一个可计算间隙不需要提前知道真正最优点。'),
('写负熵镜像子问题','在单纯形上最小化线性模型加 KL 散度；固定旧 x 时，这是严格凸问题。',r'\min_{z\in\Delta}\ \alpha g^Tz+\sum_i z_i\log(z_i/x_i).','这里的“距离”不是图中三角形上的欧氏距离。'),
('使用等式乘子求候选','对正 zᵢ 求导，得到 αgᵢ+log(zᵢ/xᵢ)+1+ν=0，再解指数式。',r'z_i=x_i e^{-\alpha g_i-1-\nu}.','所有坐标都乘上与梯度有关的权重。'),
('归一化并证明全局最优','用 Σzᵢ=1 消去公共因子。候选严格正且满足凸 KKT，因此为唯一最小点。',r'x_i^+=\frac{x_i e^{-\alpha g_i}}{\sum_jx_j e^{-\alpha g_j}}.','任意坐标都不会在精确有限一步突然成为零。'),
('指出几何和计算边界','负熵散度一般不对称；数值指数要减公共最大指数保证稳定，这不会改变归一化后的比值。',r'D_h(z,x)=\sum_i z_i\log(z_i/x_i)\ne D_h(x,z)\text{ 一般成立。}','重心图只是概率坐标的展示，不改变实际散度。')])

setp('matrix','核范数邻近为什么必须对奇异值软阈值？','A 为实矩阵，τ≥0；目标 τ‖X‖*+‖X−A‖_F²/2。引用迹不等式后给出其使用的完整过程。','矩阵把圆拉成椭圆；核范数惩罚缩短主轴，不是删掉坐标表格里比较小的条目。',[
('把输入分成方向与伸缩','取 A=UΣVᵀ，奇异值 σᵢ≥0。它们是各主轴上的伸缩量，核范数是它们的和。',r'A=U\operatorname{diag}(\sigma_i)V^T,\quad\|A\|_* =\sum_i\sigma_i.','非对称矩阵也有左右两个正交方向系。'),
('展开 Frobenius 平方','设 X 的奇异值为 sᵢ≥0。平方距离由两个平方范数和一个迹内积组成。',r'\|X-A\|_F^2=\|X\|_F^2+\|A\|_F^2-2\operatorname{tr}(X^TA).','给定伸缩长度，剩下要选的是方向对齐程度。'),
('对齐方向不会更差','von Neumann 迹不等式给 tr(XᵀA)≤Σsᵢσᵢ；按相同降序排列，X=U diag(sᵢ)Vᵀ 达到等号。',r'\operatorname{tr}(X^TA)\le\sum_i s_i\sigma_i\Rightarrow\|X-A\|_F^2\ge\sum_i(s_i-\sigma_i)^2.','方向一致时，在相同谱下离 A 最近。迹不等式的推导见紧接的补充证明。'),
('转成独立标量问题','核范数只取决于 sᵢ，所以矩阵目标不小于各标量目标之和，且对齐构造可以实现该下界。',r'\min_{s_i\ge0}\sum_i[\tau s_i+\tfrac12(s_i-\sigma_i)^2].','现在才能合法地逐主轴阈值。'),
('解非负一维二次问题','无约束极小为 σᵢ−τ；若它为负，则最小点在可行端点 0。',r's_i^*=\max(\sigma_i-\tau,0).','一根主轴缩到零时，秩才下降。'),
('恢复矩阵并说明唯一性','对齐方向后达到上述全局下界。平方距离强凸，故得到的最优矩阵唯一，即使奇异向量表示不唯一。',r'X^*=U\operatorname{diag}((\sigma_i-\tau)_+)V^T.','重奇异值会影响分解的表示，不会影响唯一邻近矩阵。')])
extra('matrix','迹不等式的有限维推导','矩阵用补零方式视为同阶方阵；奇异值按非增序排列。以下给出证明中需要的 von Neumann 上界。','两个正交方向系的重叠权重，每行每列总量都不超过一；最好的配对让大伸缩对上大伸缩。',[
('展开两套奇异向量','令 X=Σsᵢuᵢvᵢᵀ，A=Σσⱼpⱼqⱼᵀ，代入迹的双线性展开。',r'\operatorname{tr}(X^TA)=\sum_{i,j}s_i\sigma_j(u_i^Tp_j)(v_i^Tq_j).','每一对方向只通过两个内积产生贡献。'),
('用非负重叠权重上界','取 Wᵢⱼ=|(uᵢᵀpⱼ)(vᵢᵀqⱼ)|。按行与按列分别使用 Cauchy–Schwarz 和正交基平方和等于一。',r'W_{ij}\ge0,\quad\sum_jW_{ij}\le1,\quad\sum_iW_{ij}\le1.','这是双次随机权重，不是任意可以放大的配对。'),
('把乘积写成二维面积积分','非负数的乘积等于两个指标函数乘积的积分，对有限求和可交换求和与积分。',r's_i\sigma_j=\int_0^\infty\!\int_0^\infty\mathbf1_{t<s_i}\mathbf1_{u<\sigma_j}\,dt\,du.','一根长条的面积被分解成许多阈值小块。'),
('控制每个阈值矩形中的总权重','令 I_t={i:sᵢ>t}、J_u={j:σⱼ>u}。行和列预算各给一条界，取两者较小值。',r'\sum_{i\in I_t,j\in J_u}W_{ij}\le\min(|I_t|,|J_u|).','矩形里总配对质量不会超过较少的一边。'),
('对齐降序达到阈值上界','降序时 I、J 都是前缀，公共前缀长度正是较小者。积分后得到对齐奇异值的乘积和。',r'\sum_{ij}s_i\sigma_jW_{ij}\le\int\!\int\min(|I_t|,|J_u|)\,dt\,du=\sum_i s_i\sigma_i.','所有阈值都同时由同序配对达到最佳。'),
('回到迹并核对等号构造','最初迹不大于绝对重叠权重和，后者不大于同序乘积和；同奇异向量构造给出 W 的单位配对。',r'\operatorname{tr}(X^TA)\le\sum_i s_i\sigma_i,\quad X=U\operatorname{diag}(s_i)V^T\text{ 与 }A\text{ 同向时取等。}','这补上“为什么可以只优化奇异值”的方向论证。')],scene='nuclear')

setp('maxcut','三角形的整数最优、SDP 上界与舍入概率','无权三角形；单位向量取二维平面。舍入用过原点且法向均匀的直线；一般高维概率可限制到两个向量张成的平面。','松弛允许三个向量两两相隔 120°，而二元标签只能分成两组，无法让三条边同时异号。',[
('边是否被割由符号乘积决定','同号乘积为 1、异号为 −1，所以 (1−sᵢsⱼ)/2 恰是割边指示函数。',r'\operatorname{cut}(s)=\sum_{i<j}(1-s_is_j)/2.','这是整数答案，不是连续松弛值。'),
('证明三条边不能全割','三个符号乘积关系为 (s₁s₂)(s₂s₃)(s₁s₃)=1；若三条都异号，左边会是 −1，矛盾。',r'(s_1s_2)(s_2s_3)(s_1s_3)=s_1^2s_2^2s_3^2=1.','奇环不能让每条相邻关系都相反。'),
('构造达到两条的割','取标签 (1,1,−1)，与第三点相连的两条边被割，故整数最优恰为 2。',r'\max_s\operatorname{cut}(s)=2.','上界和可行构造一起给出精确最优。'),
('单位向量的平方和给 SDP 上界','展开三个单位向量和的平方范数，它非负。移项限制两两内积之和。',r'0\le\|v_1+v_2+v_3\|^2=3+2\sum_{i<j}v_i^Tv_j\Rightarrow\operatorname{SDP}\le9/4.','松弛上界来自一个始终非负的平方。'),
('等角向量达到上界','平面上取角度 0、2π/3、4π/3，向量和为零，任意两向量内积为 −1/2。',r'\operatorname{SDP}=3\cdot\tfrac{1-(-1/2)}2=9/4.','2.25 是松弛值，不可能是当前图的整数割边数。'),
('计算一对向量的异号扇区','设两向量夹角 θ∈[0,π]，法向旋转一周时，点积异号的角区总长度为 2θ，总角长为 2π。',r'\mathbb P[s_i\ne s_j]=2\theta/(2\pi)=\theta/\pi=\arccos(v_i^Tv_j)/\pi.','动画中让法向扫过一周，观察异号扇区的长度。'),
('利用期望线性性求总割','各边是否被割可以相关，但求期望只需逐边概率相加；等角三角形给出 3×2/3=2。',r'\mathbb E[\operatorname{cut}]=\sum_{i<j}\arccos(v_i^Tv_j)/\pi.','不需要伪造一组随机实验均值来展示解析期望。')])

setp('group','组 L₂ 邻近：为什么整组一起归零？','v∈ℝⁿ，τ≥0；目标 τ‖z‖₂+‖z−v‖²/2。各组不重叠时可逐组应用。','距离项希望朝向 v；L₂ 惩罚不偏爱任何角度，只惩罚半径，因此方向保留、半径收缩。',[
('先固定候选半径','写 r=‖z‖、a=‖v‖，展开平方距离；唯有内积依赖方向。',r'\|z-v\|^2=r^2+a^2-2z^Tv.','同半径的所有候选形成一个圆。'),
('最好的方向与输入对齐','Cauchy–Schwarz 给 zᵀv≤ra；v≠0 时，取 z=(r/a)v 达到等号。',r'\|z-v\|^2\ge(r-a)^2,\quad z=(r/a)v\text{ 时取等。}','旋转到与 v 同向，只会降低距离成本。'),
('只剩一个非负半径问题','方向已解决，把目标化为 r≥0 上的二次函数。',r'\min_{r\ge0}\ \tau r+\tfrac12(r-a)^2.','组收缩是一个半径的一维软阈值。'),
('求半径并考虑边界','无约束驻点为 a−τ；若为负，最小值在 r=0。',r'r^*=(a-\tau)_+.','阈值超过整组长度时，所有坐标同时归零。'),
('恢复向量并处理零输入','当 a>0，乘回单位方向；a=0 时原问题显然在 z=0 唯一最优，避免除以零。',r'z^*=\begin{cases}(1-\tau/\|v\|)_+v,&v\ne0,\\0,&v=0.\end{cases}','实现必须显式处理零向量。'),
('用零点次微分再独立核对','范数在零点的次微分是单位球。因此零点最优当且仅当输入范数不超过 τ，与半径推导一致。',r'\partial\|0\|_2=\{w:\|w\|\le1\},\quad0\in-v+\tau\partial\|0\|_2\iff\|v\|\le\tau.','两个独立推导都指出是“组范数”触发归零。')])

setp('complexity','把收敛阶变成明确的迭代预算','沿用 PG、FISTA 的凸复合、L 光滑、精确 prox 假设；D=‖x₀−x*‖，目标精度 ε>0。只比较每轮相同的一次梯度与一次 prox。','理论界是一张保守预算表，不是每条真实轨迹的导航线。',[
('明确界的来源与常数','PG 的界来自距离望远镜求和，FISTA 的界来自加权势函数；前面两节已经给出完整证明。',r'\Delta_k^{\rm PG}\le LD^2/(2k),\quad\Delta_k^{\rm FISTA}\le2LD^2/(k+1)^2.','切换到对应证明可检查每个不等式，不把 O 符号当黑箱。'),
('给 PG 解精度不等式','要使保守上界不超过 ε，移项得到 k 的充分下界；实际所需轮数可能更少。',r'LD^2/(2k)\le\varepsilon\iff k\ge LD^2/(2\varepsilon).','界保证不晚于某个预算，但不预言恰在哪轮停止。'),
('给 FISTA 解平方不等式','两边正数取平方根，再减一。最后取不小于 1 的整数轮数。',r'2LD^2/(k+1)^2\le\varepsilon\iff k\ge\sqrt{2LD^2/\varepsilon}-1.','ε 缩小一百倍，最坏预算量级一个增百倍、一个增十倍。'),
('不要把理论参照喂给算法','x* 只用于检验和画 gap，不参与算法更新。二次教学实例由独立活动集求解器获得参照点。',r'\Delta_k=F(x_k^{\rm computed})-F(x^*).','实线必须由真实迭代产生，不能照着上界生成。'),
('说明公平成本口径','本节两种算法每轮各做一次梯度和 prox；ADMM、PPA、BCD 的一次按钮操作并不代表相同代价。',r'\operatorname{cost}_{\rm PG}(k)=\operatorname{cost}_{\rm FISTA}(k)=k\text{ 次梯度}+k\text{ 次 prox}.','不声称相同原语次数就必然相同墙钟时间。'),
('有限精度与边界解释','计算差值可以因舍入出现很小负数；对数图只为显示进行正数截底，导出仍保留原值。测试的容差应与数值尺度匹配。',r'\Delta_k\le B_k+\varepsilon_{\rm test},\quad\text{绘图值}=\log_{10}(\max(\Delta_k,\delta_{\rm plot})).','平坦尾部不等于数学上的精确有限终止。')],scene='rates')

