# Verified zero-penalty and generalized-chain-rule refinement.
_ssn_refinement = {'proof': {'title': '分段 Newton 线性化、可逆性与局部速率', 'assumptions': 't>0，Q 正定，λ≥0；实现选择二值 Newton 掩码。λ=0 时软阈值是恒等映射，必须取 D=I。局部速率由直接余项验证与一致有界的逆矩阵推出；完整步与保护步分开。', 'idea': '尖点把空间切成不同线性片区；牛顿不必抹平尖点，只需知道当前片区如何把输入变成残差。', 'scene': 'semismooth', 'kind': '教学重编证明', 'refs': [{'doc': 's064', 'start': 542, 'end': 568}, {'doc': 's063', 'start': 5, 'end': 38}]}, 'derivation': [{'title': '从最优条件得到不动点', 'text': 'prox 的最优条件告诉我们：x=prox_{tλ‖·‖₁}(x−t(Qx−b)) 等价于原问题的次梯度平衡。', 'math': 'R(x)=x-S_{t\\lambda}(x-t(Qx-b)),\\quad R(x)=0\\iff0\\in Qx-b+\\lambda\\partial\\|x\\|_1.', 'hint': '阈值一定是 tλ，而不是 t。'}, {'title': '逐片区求斜率并单独处理 λ=0', 'text': 'λ>0 时，软阈值在阈值外斜率为 1、阈值内为 0；折点的广义标量斜率为 [0,1]，这里选其二值端点。λ=0 时两个折点消失，整个函数就是恒等映射，包括零点也只有斜率 1。', 'math': 'D_{ii}=\\begin{cases}1,&\\lambda=0,\\\\1,&\\lambda>0,\\ |v_i|>t\\lambda,\\\\0,&\\lambda>0,\\ |v_i|<t\\lambda,\\\\0\\text{ 或 }1,&\\lambda>0,\\ |v_i|=t\\lambda.\\end{cases}', 'hint': '零惩罚不是尖点情形；此时应恢复光滑二次问题的 Newton 矩阵。'}, {'title': '构造分段 Newton 矩阵', 'text': 'v 对 x 的导数为 A=I−tQ。每个光滑片区中直接求导得到下式；在折点处把所选斜率代入构造 Newton 线性化。A 奇异时不能直接把广义链式法则的包含关系当成等号，也不宣称每个掩码产生的矩阵都属于残差的 Clarke Jacobian；下一步直接验证所需的余项。', 'math': 'A=I-tQ,\\qquad J(x)=I-D(v)A=I-D(v)+tD(v)Q.', 'hint': '算法需要一个具有正确余项的 Newton 模型；不必滥用广义导数集合的等式。'}, {'title': '解释二值掩码下的可逆性', 'text': '按非活动、活动坐标重排，J 是块下三角：非活动行是单位阵，活动主块是 tQ_AA。Q 正定使主子矩阵正定。', 'math': 'J=\\begin{pmatrix}I&0\\\\tQ_{AI}&tQ_{AA}\\end{pmatrix},\\quad Q_{AA}\\succ0\\Rightarrow J\\text{ 可逆。}', 'hint': '这项保证依赖 Q 正定和当前残差结构。'}, {'title': '不依赖集合等号，直接验证余项', 'text': '令 e=x−x*，v*=Ax*+tb。软阈值只有有限个折点。x 足够接近根时，v* 不在折点的坐标不会跨越折点；v* 在折点的坐标，从 v* 到 v 的线段位于一条仿射支段内，所以任意选定端点斜率都精确描述该增量。λ=0 则使用恒等斜率。逐坐标合并得到 LASSO 的零余项。对更一般的半光滑 Newton 模型，只需把零替换为 o(‖e‖) 或 O(‖e‖²)。', 'math': 'R(x)-R(x^*)-J(x)e=-[S_{t\\lambda}(v)-S_{t\\lambda}(v^*)-D(v)(v-v^*)]=0\\quad(x\\text{ 充分近}).', 'hint': '只比较真实输入增量与当前分段斜率，奇异的 A 也不会破坏这个等式。'}, {'title': '推导完整牛顿步误差', 'text': 'R(x*)=0，完整步 x⁺=x−J⁻¹R(x)，于是误差等于负的逆矩阵乘线性余项。', 'math': 'e^+=-J^{-1}[R(x)-R(x^*)-Je].', 'hint': '代数形式与光滑牛顿相似，但余项的定义不同。'}, {'title': '由有界逆得到速率', 'text': 'Q 正定使每一个二值掩码下的矩阵可逆，有限个掩码给出逆范数的共同上界 M。对一般的 o(‖e‖) 或 O(‖e‖²) 余项取范数，就分别得到超线性或二次速率；初值足够近保证迭代留在该邻域。这里分段仿射 LASSO 的零余项还给出更强的精确算术性质。', 'math': '\\|e^+\\|=o(\\|e\\|),\\quad\\text{强半光滑时 }\\|e^+\\|=O(\\|e\\|^2).', 'hint': '超线性或二次结论不等于任意远处初值都收敛。'}, {'title': '活动片区稳定时的特例', 'text': 'LASSO 残差在固定片区内仿射。若当前点、根和完整步都处于同一有效片区，线性余项为零，精确牛顿一次到根。', 'math': 'R(x)=Jx+c\\Rightarrow x-J^{-1}R(x)=-J^{-1}c=x^*.', 'hint': '跨片区或回溯缩步时，不能无条件声称一步终止。'}]}
D['semismooth']['proof'] = _ssn_refinement['proof']
D['semismooth']['derivation'] = _ssn_refinement['derivation']

